import json
from pathlib import Path
B=Path(__file__).resolve().parents[1]
IDS=json.loads((B/'inputs/eight-current-whole-DE-EN-goals.exact.json').read_text())['goalIds']
records=[]
def C(cid,title,material,task,solution,transfer,tsolution,limits,rubrics):
 d={'id':cid,'titleDe':title[0],'titleEn':title[1],'syntheticData':True}
 for key,pair in [('material',material),('task',task),('workedSolution',solution),('freshTransfer',transfer),('freshTransferSolution',tsolution),('limits',limits)]:
  d[key+'De'],d[key+'En']=pair
 d['rubric']=[{'id':cid+'-r'+str(i+1),'expectationIds':['e'+str(i+1)],'criterionDe':r[0],'criterionEn':r[1]} for i,r in enumerate(rubrics)]
 return d
def R(index,archetype,exps,axes,cases):
 profile={'archetype':archetype,'expectations':[{'id':'e'+str(i+1),'essentialUnderstandingDe':e[0],'essentialUnderstandingEn':e[1],'observablePerformanceDe':e[2],'observablePerformanceEn':e[3]} for i,e in enumerate(exps)],'coverageExpectations':{'requiredExpectationIds':['e1','e2','e3'],'alternativeExpectationGroups':[],'minimumIndependentDemonstrations':2,'freshVariationRequired':True,'independentTransferRequired':True},'variationAxes':[{'id':'v'+str(i+1),'textDe':a[0],'textEn':a[1]} for i,a in enumerate(axes)],'applicationCaseBriefs':[{'id':c['id'],'taskDemandDe':c['taskDe'],'taskDemandEn':c['taskEn'],'expectedPerformanceDe':c['workedSolutionDe'],'expectedPerformanceEn':c['workedSolutionEn'],'understandingFocusDe':exps[0][0]+' '+exps[1][0]+' '+exps[2][0],'understandingFocusEn':exps[0][1]+' '+exps[1][1]+' '+exps[2][1]} for c in cases]}
 records.append({'goalId':IDS[index],'profile':profile,'cases':cases})

R(0,'experiment',[
('Im Gewebe stehen benachbarte Pflanzenzellen in einem räumlichen Verband; die sichtbare Zellwand ist von der meist nicht getrennt aufgelösten Zellmembran zu unterscheiden.','Plant tissue consists of spatially connected neighbouring cells; visible cell walls differ from cell membranes, which are usually not resolved separately.','Die lernende Person beschreibt geordnete Zellgrenzen, Lage und beobachtbare Strukturen am Präparat oder gekennzeichneten schematischen Feld.','The learner describes ordered cell boundaries, arrangement and observable structures in a specimen or labelled schematic field.'),
('Präparation, Vergrößerung, Maßstab und Fokussierung bestimmen die Beobachtung; fehlende Sichtbarkeit ist kein Nachweis für das Fehlen einer Struktur.','Preparation, magnification, scale and focus affect observations; invisibility does not prove a structure is absent.','Die lernende Person plant und protokolliert eine sichere Mikroskopbeobachtung und trennt Beobachtung von Deutung.','The learner plans and records safe microscopy and separates observation from interpretation.'),
('Verschiedene Gewebe haben unterschiedliche Merkmale; Zwiebel-Bulbenepidermis und grünes Blattgewebe lassen sich begründet vergleichen.','Different tissues have different traits; onion bulb epidermis and green leaf tissue can be compared with reasons.','Die lernende Person überträgt die Beschreibung auf einen neuen Ausschnitt und begründet Grenzen der Zell- und Gewebezuordnung.','The learner applies the description to a new field and explains limits of cell and tissue identification.')],
[('Zwiebel-Bulbenepidermis versus Blattgewebe','Onion bulb epidermis versus leaf tissue'),('Ganze Zellreihe versus angeschnittener oder unscharfer Ausschnitt','Complete cell row versus cut-off or blurred field')],[
C('plant-tissue-c1',('Zwiebelhaut als Zellverband beobachten','Observe onion epidermis as a cell association'),
('Material: Lichtmikroskop, Objektträger, Deckglas, Pipette, Wasser, Pinzette und vorbereitete dünne Zwiebel-Bulbenepidermis; eine Lehrkraft schneidet das Material. Schematische Übersicht im zugehörigen PNG: zusammenhängende rechteckige Zellen. Synthetisches Beobachtungsprotokoll bei 100×: Feld mit drei aneinandergrenzenden Zellreihen, klaren Grenzen; bei 400× nach schulgeeigneter Färbung einzelne dunkle rundliche Strukturen. Kalibrierte Messstrecke: 500 µm reichen über fünf ungefähr gleich lange Zellen. Zellmembran und einzelne Organellen sind hier nicht separat aufgelöst.','Materials: light microscope, slide, coverslip, dropper, water, forceps and prepared thin onion bulb epidermis; a teacher cuts the material. The associated PNG supplies a schematic overview of connected rectangular cells. Synthetic observation record at 100×: three adjoining cell rows with clear boundaries; at 400× after a school-appropriate stain, some dark rounded structures. Calibrated distance: 500 µm spans five approximately equal-length cells. Cell membranes and individual organelles are not resolved separately here.'),
('Beschreibe eine sichere Abfolge zum Präparieren, Finden und Fokussieren des Gewebes. Zeichne oder beschreibe mindestens drei benachbarte Zellen mit Maßstab und schätze die Zelllänge. Trenne drei sichtbare Befunde von Deutungen; begründe, warum der Zellverband und nicht nur eine isolierte Zelle beschrieben wird.','Describe a safe sequence for preparing, finding and focusing the tissue. Draw or describe at least three neighbouring cells with a scale and estimate cell length. Separate three visible findings from interpretations; explain why this describes tissue rather than an isolated cell.'),
('Eine dünne Epidermislage in einen Wassertropfen legen, Deckglas schräg blasenarm absenken, mit kleinstem Objektiv beginnen, Präparat zentrieren und bei größerer Vergrößerung nur fein fokussieren; Objektiv darf das Glas nicht berühren. Sichtbar: benachbarte rechteckige Umrisse, gemeinsame Grenzlinien und einzelne dunkle rundliche Strukturen. Deutung: Zellwände begrenzen Pflanzenzellen; gefärbte Rundstrukturen sind mit Zellkernen vereinbar. Länge etwa 500/5 = 100 µm. Die Zeichnung zeigt mehrere direkt anschließende Zellen im selben Verband. Eine separat nicht sichtbare Membran ist nicht als fehlend zu bewerten; dieses nichtgrüne Zwiebelgewebe zeigt keine Chloroplasten.','Place a thin epidermal layer in a water drop, lower the coverslip at an angle to limit bubbles, start with the lowest objective, centre the specimen and use only fine focus at higher magnification; the objective must not touch the glass. Visible findings are adjoining rectangular outlines, shared boundary lines and some dark rounded structures. Interpretation: cell walls delimit plant cells; stained rounded structures are consistent with nuclei. Length is about 500/5 = 100 µm. The drawing shows several directly adjacent cells in the same tissue. An unresolved membrane is not judged absent; this non-green onion tissue shows no chloroplasts.'),
('Neues Feld: dieselben Zellen sind bei stärkerer Vergrößerung teilweise am Bildrand abgeschnitten; in einer Zelle ist kein Kern sichtbar. Wie beschreibst du den Ausschnitt, ohne fehlende Zellverbände oder kernlose Zellen zu behaupten?','New field: at higher magnification, the same cells are partly cut off at the image edge; one cell has no visible nucleus. How do you describe it without claiming that tissue connections or nuclei are absent?'),
('Angeschnittene Umrisse und Nachbargrenzen werden als Teilansicht bezeichnet. Der Verband ist am Übersichtsbild gesichert. Ein Kern kann außerhalb der Fokusebene liegen oder unzureichend gefärbt sein; beschrieben wird nicht sichtbar, nicht fehlt.','Cut-off outlines and neighbouring boundaries are described as a partial view. The overview supports tissue continuity. A nucleus may be outside the focal plane or inadequately stained; the correct description is not visible rather than absent.'),
('Die Protokolle und Längen sind synthetisch; eine wirkliche Präparation ist eine mögliche schulische Durchführung, keine bereits erbrachte Lernendenleistung. Färbemittel nach Schulvorgaben; Glasscherben und Objektivkontakt vermeiden.','Records and lengths are synthetic; actual preparation is a possible school activity, not evidence of completed learner work. Use stains under school rules; avoid broken glass and objective contact.'),
[('Mindestens drei Nachbarzellen und gemeinsame Zellwandgrenzen beschreiben; Gewebeverband benennen.','Describe at least three neighbouring cells and shared cell-wall boundaries; identify tissue organisation.'),('Sichere Mikroskopabfolge, Maßstab 100 µm und Beobachtung/Deutung sauber trennen.','Give a safe microscopy sequence, the 100 µm estimate and separate observation from interpretation.'),('Den neuen Rand-/Fokusbefund ohne unbelegte Abwesenheitsbehauptung erklären.','Explain the new edge/focus finding without unsupported claims of absence.')]),
C('plant-tissue-c2',('Grünes Blattgewebe vergleichen','Compare green leaf tissue'),
('Zwei didaktische Felder: A Zwiebel-Bulbenepidermis mit zusammenhängenden Zellwänden, keinen sichtbaren grünen Körpern; B dünnes Wasserpestblatt mit verbundenen länglichen Zellen und vielen grünen Körpern am Rand des Zellinneren. Das PNG zeigt beide Gewebemuster schematisch. Synthetische Messung B: drei Zelllängen entlang einer kalibrierten Strecke von 180 µm. Ein dichter doppelter Blattabschnitt wirkt unscharf und dunkler; das dünne einschichtige Blattstück zeigt klare Grenzen.','Two teaching fields: A onion bulb epidermis with connected cell walls and no visible green bodies; B a thin Elodea leaf with connected elongated cells and many green bodies near the inner cell edges. The PNG illustrates both tissue patterns schematically. Synthetic measurement for B: three cell lengths span a calibrated 180 µm. A thick doubled leaf section looks blurred and darker; a thin single-layer section shows clear boundaries.'),
('Beschreibe beide Zellverbände nach gemeinsamen und unterschiedlichen sichtbaren Merkmalen. Berechne die ungefähre Zelllänge in B. Plane, wie du für B ein geeignetes Präparat und eine beschriftete Beobachtungszeichnung erhältst. Prüfe die Aussage: Pflanzenzellen müssen immer grün sein.','Describe similarities and differences visible in the two cell associations. Calculate approximate cell length in B. Plan a suitable preparation and labelled observation drawing for B. Evaluate the claim that plant cells must always be green.'),
('Beide Felder zeigen aneinanderliegende Zellen mit festen Grenzlinien/Zellwänden; B zeigt zusätzlich grüne Chloroplasten, A nicht. B-Länge: 180/3 = 60 µm. Ein dünnes Blattstück flach in Wasser und unter Deckglas legen, klein beginnen, geeignete einzelne Zelllage finden und fein fokussieren; Zeichnung mehrerer Nachbarzellen mit Maßstab und nur tatsächlich erkennbaren Strukturen. Die Bulbenepidermis ist ein Gegenbeispiel zur Immer-grün-Aussage. Pflanzengewebe unterscheiden sich in Bau und Aufgabe; unscharfe Überlagerungen eignen sich nicht für sichere Einzelzellbeschreibung.','Both fields show adjoining cells with firm boundary lines/cell walls; B additionally shows green chloroplasts, whereas A does not. B length: 180/3 = 60 µm. Place a thin leaf piece flat in water under a coverslip, start at low magnification, find a suitable single layer and fine-focus; draw multiple neighbouring cells with a scale and only structures actually discernible. Bulb epidermis disproves the always-green claim. Plant tissues differ in structure and function; blurred overlapping layers are unsuitable for reliable individual-cell descriptions.'),
('Ein neuer ungefärbter Wurzelabschnitt zeigt verbundene Zellwände, aber weder grüne Körper noch klar sichtbare Kerne. Welche Aussagen über Pflanzengewebe sind gesichert, welche brauchen andere Präparation oder Information?','A new unstained root section shows connected cell walls but neither green bodies nor clear nuclei. Which statements about plant tissue are supported, and which need another preparation or information?'),
('Die zusammenhängenden Zellgrenzen stützen die Beschreibung eines Zellverbandes. Aus dem bereitgestellten Wurzelkontext ist Pflanzengewebe plausibel; nichtgrüne Zellen sind erwartbar. Unsichtbare Kerne oder Chloroplasten allein erlauben keine vollständige Organelleninventur oder sichere unbekannte Artbestimmung. Dünnere Schnitte/Färbung können Kernbeobachtung verbessern.','Connected boundaries support a cell-association description. The supplied root context supports plant tissue; non-green cells are expected. Invisible nuclei or chloroplasts alone do not establish a full organelle inventory or reliably identify an unknown species. Thinner sections or staining may improve nucleus observation.'),
('Schemata und synthetische Beobachtungen ersetzen kein echtes Mikroskopfoto und werden nicht als reale Messdaten etikettiert. Alle Längen sind bereitgestellte Übungsdaten.','Schematics and synthetic observations are not actual micrographs and are not labelled real measurements. All lengths are supplied practice data.'),
[('Gemeinsame Gewebestruktur und unterschiedliche Chloroplastensichtbarkeit materialgestützt beschreiben.','Use the material to describe shared tissue organisation and different chloroplast visibility.'),('60 µm und Präparations-/Fokussierungsentscheidung nachvollziehbar begründen.','Explain the 60 µm estimate and preparation/focusing choices.'),('Nichtgrünes Wurzelgewebe und fehlende Sichtbarkeit im frischen Fall korrekt einordnen.','Correctly interpret non-green root tissue and invisibility in the fresh case.')])])

R(1,'modeling',[
('Menschen tauschen Stoffe und Energie mit der Umgebung aus: Nahrung liefert Energieträger und Baustoffe, Sauerstoff unterstützt oxidative Energieumwandlung.','Humans exchange matter and energy with their surroundings: food supplies energy carriers and building materials; oxygen supports oxidative energy conversion.','Die lernende Person ordnet Stoffeingänge, Umbau, Speicherung und Ausgänge sowie Energieabgabe in einem Systemmodell.','The learner organises matter inputs, conversion, storage and outputs, together with energy release, in a system model.'),
('Konstante Körpermasse schließt große Stoffflüsse nicht aus; Wärme ist Energieabgabe, kein ausgeschiedener Stoff.','Constant body mass does not exclude large matter flows; heat is energy output rather than an excreted substance.','Die lernende Person beschreibt Stoff- und Energiebilanzen getrennt und erklärt den offenen Systemcharakter.','The learner describes matter and energy balances separately and explains why the system is open.'),
('Baustoff-, Energie- und Regulationsfunktionen hängen vom Stoff und Kontext ab; Wasser, Mineralstoffe und Sauerstoff sind keine kalorischen Energieträger.','Building, energy and regulatory roles depend on the substance and context; water, minerals and oxygen are not caloric energy carriers.','Die lernende Person wendet das Modell auf Ruhe, Bewegung oder Wachstum an und benennt seine Grenzen.','The learner applies the model to rest, movement or growth and identifies its limits.')],
[('Gleichbleibende Masse versus Aufbau oder Speicherabbau','Stable mass versus growth or reserve use'),('Stoffmengen versus Energieflüsse','Matter amounts versus energy flows')],[
C('open-system-c1',('Gleiche Masse trotz Stoffaustausch','Stable mass despite matter exchange'),
('Synthetisches Tagesmodell ohne individuelle Gesundheitsbewertung: Eingänge 0,8 kg Nahrung, 2,2 kg Wasser, 0,6 kg aufgenommener Sauerstoff; Ausgänge 0,7 kg Kohlenstoffdioxid, 2,7 kg Wasser über Atmung/Haut/Urin, 0,2 kg weitere ausgeschiedene Stoffe. Lebensmittelenergie 9 000 kJ; bei ungefähr konstanten Energiespeichern gehen 8 500 kJ als Wärme und 500 kJ als äußere mechanische Arbeit ab. Stoffe werden im Körper umgebaut. Die Zahlen sind ein vereinfachtes ausgeglichenes Modell.','Synthetic daily model without individual health evaluation: inputs are 0.8 kg food, 2.2 kg water and 0.6 kg absorbed oxygen; outputs are 0.7 kg carbon dioxide, 2.7 kg water through breathing/skin/urine and 0.2 kg other excreted matter. Food supplies 9,000 kJ; with approximately constant energy stores, 8,500 kJ leaves as heat and 500 kJ as external mechanical work. Matter is transformed inside the body. These numbers form a simplified balanced model.'),
('Zeichne das offene System mit Stoff- und Energiepfeilen. Prüfe die Massenbilanz und erläutere, warum gleiche Körpermasse kein geschlossenes System bedeutet. Ordne Nahrung, Wasser und Sauerstoff nach Funktion; erläutere Baustoffnutzung am Beispiel eines Nahrungsproteins.','Draw the open system with matter and energy arrows. Check the mass balance and explain why stable body mass does not mean a closed system. Assign roles to food, water and oxygen; explain building-material use using a dietary protein.'),
('Stoffeingang 0,8+2,2+0,6 = 3,6 kg; Ausgang 0,7+2,7+0,2 = 3,6 kg, also Speicher-/Massenänderung im Modell null trotz dauernden Austauschs. Nahrung liefert chemische Energie und Bausteine: Proteine werden verdaut, Aminosäuren können für körpereigene Proteine genutzt werden. Wasser ist Lösungsmittel/Transport- und Reaktionsmedium; Sauerstoff ist ein Reaktionspartner der Zellatmung, kein eigener kalorischer Brennstoff. Energie 9 000 = 8 500+500 kJ. Wärme hat einen eigenen Energiepfeil und wird nicht zu den kg Stoffausgang addiert.','Matter input is 0.8+2.2+0.6 = 3.6 kg; output is 0.7+2.7+0.2 = 3.6 kg, so model reserve/mass change is zero despite continuous exchange. Food supplies chemical energy and building blocks: proteins are digested and amino acids can build body proteins. Water serves as solvent, transport and reaction medium; oxygen is a cellular-respiration reactant, not a caloric fuel itself. Energy: 9,000 = 8,500+500 kJ. Heat has its own energy arrow and is not added to kilograms of matter output.'),
('Neues Modell: Stoffeingang 3,7 kg, Stoffausgang 3,6 kg. Energiespeicherung wird mit 300 kJ angegeben. Darf man daraus schließen, die zusätzlichen 0,1 kg seien ausschließlich Fett?','New model: 3.7 kg matter enters and 3.6 kg leaves. Energy storage is given as 300 kJ. Can one conclude that the additional 0.1 kg consists entirely of fat?'),
('Die Massenänderung beträgt +0,1 kg. Zusammensetzung bleibt offen: Wasser, gespeicherte Nährstoffe oder Aufbau können beitragen. Die getrennte Energiespeicherangabe beweist keine reine Fettmasse. Beide Bilanzen benötigen denselben abgegrenzten Zeitraum.','Mass change is +0.1 kg. Composition remains uncertain: water, stored nutrients or tissue growth may contribute. The separate energy-storage figure does not prove pure fat mass. Both balances require the same defined time period.'),
('Keine Ernährungs- oder klinische Empfehlung. Die synthetische Bilanz vereinfacht nicht separat erfasste Teilflüsse; Energieumsatz und Massenfluss sind unterschiedliche Größen.','No dietary or clinical recommendation. The synthetic balance simplifies flows not recorded separately; energy expenditure and matter flow are different quantities.'),
[('Energie- und Baustofffunktion sowie Sauerstoff- und Wasserrolle korrekt darstellen.','Correctly represent energy/building functions and oxygen/water roles.'),('3,6 kg auf beiden Seiten, 9 000 kJ Energiebilanz und offenen Austausch begründen.','Explain 3.6 kg on both sides, the 9,000 kJ energy balance and open exchange.'),('Neue +0,1 kg ohne unbelegte Fettzuordnung deuten.','Interpret the new +0.1 kg without an unsupported fat assignment.')]),
C('open-system-c2',('Arbeit und Aufbau im offenen System','Work and growth in an open system'),
('Zwei vereinfachte synthetische Karten: A Ruhe – 8 000 kJ Nahrungsenergie, 7 800 kJ Wärme, 200 kJ äußere Arbeit, Energiespeicher unverändert. B Bewegung – 8 000 kJ Nahrung, 10 000 kJ Energieabgabe als Wärme und Arbeit, körpereigene Reserven liefern die Differenz. In beiden Karten werden Sauerstoff aufgenommen und CO₂, Wasser und Ausscheidungsstoffe abgegeben. Zusatzkarte Wachstum: Aminosäuren aus Nahrung werden in körpereigene Proteine eingebaut; Mineralstoffe dienen beispielsweise dem Aufbau mineralisierter Strukturen.','Two simplified synthetic cards: A rest – 8,000 kJ food energy, 7,800 kJ heat, 200 kJ external work, unchanged energy reserves. B movement – 8,000 kJ food energy, 10,000 kJ released as heat and work, body reserves provide the difference. Both take in oxygen and release CO₂, water and waste matter. Growth card: dietary amino acids are incorporated into body proteins; minerals contribute, for example, to mineralised structures.'),
('Beschreibe für A/B den offenen Stoffaustausch und vergleiche die Energieversorgung. Berechne die Speicheränderung B. Erkläre am Wachstumsbeispiel, warum Nahrung nicht allein als Brennstoff beschrieben werden darf. Prüfe, ob Wasser- oder Sauerstoffaufnahme allein die fehlende Nahrungsenergie ersetzen kann.','Describe open matter exchange in A/B and compare energy supply. Calculate reserve change in B. Use growth to explain why food cannot be described only as fuel. Evaluate whether taking in water or oxygen alone replaces missing food energy.'),
('In beiden Fällen passieren Stoffe die Systemgrenze und werden umgebaut. A: 8 000−7 800−200 = 0 kJ Speicheränderung. B: 8 000−10 000 = −2 000 kJ, Reserven werden im Modell abgebaut. Bausteine können auch bei Wachstum in Körperstrukturen bleiben; die Masse muss deshalb nicht vollständig als sofortiger Ausgang erscheinen. Wasser und Sauerstoff unterstützen Stoffwechsel, liefern aber keine kalorische Nahrungsenergie. Energie aus Reserven ersetzt kurzfristig ein Defizit im Modell; dies ist keine Aussage über sinnvolle Ernährung.','In both cases matter crosses the system boundary and is transformed. A: 8,000−7,800−200 = 0 kJ reserve change. B: 8,000−10,000 = −2,000 kJ, so reserves are used in the model. During growth, building blocks may remain in body structures; input mass need not all appear immediately as output. Water and oxygen support metabolism but supply no caloric food energy. Reserves cover a shortfall in this model; this is not a recommendation about diet.'),
('Neue Karte: Eine Person nimmt genügend chemische Energie auf, aber ein benötigter Baustoff fehlt. Reicht die Energiebilanz allein zur Beschreibung von Wachstum? Begründe im Systemmodell.','New card: a person receives enough chemical energy but lacks a required building material. Is the energy balance alone sufficient to describe growth? Explain using the system model.'),
('Nein: Einbau benötigt passende Stoffe sowie Energie. Ein ausgeglichener Energiehaushalt garantiert weder alle Bausteine noch alle Regulationsbedingungen. Stoff- und Energierollen müssen getrennt und anschließend verbunden betrachtet werden.','No: construction requires appropriate matter as well as energy. Balanced energy does not guarantee every building block or regulatory condition. Matter and energy roles must be distinguished and then connected.'),
('Die Karten sind keine Messung tatsächlicher Personen und erlauben keine Diagnose oder individuelle Aufnahmevorgabe. Sauerstoffaufnahme wird qualitativ angegeben, deshalb keine detaillierte stöchiometrische Atmungsbilanz.','Cards do not measure real people and do not support diagnosis or individual intake prescriptions. Oxygen uptake is qualitative, so no detailed stoichiometric respiration balance is inferred.'),
[('Stoffaufnahme, Umbau und Abgabe als Systemaustausch beschreiben.','Describe uptake, transformation and output as system exchange.'),('0 und −2 000 kJ korrekt bilanzieren; Wärme von Stoffen trennen.','Correctly calculate 0 and −2,000 kJ; distinguish heat from matter.'),('Aufbau verlangt passende Bausteine trotz ausreichender Energie erklären.','Explain why construction needs suitable building blocks despite enough energy.')])])

R(2,'experiment',[
('Ein kontrollierter Versuch verändert einen Außenfaktor und operationalisiert Enzymaktivität über eine anfängliche Produktbildungsrate; gleiche Ansätze, Leerwerte und Wiederholungen begrenzen Störfaktoren.','A controlled experiment varies one external factor and operationalises enzyme activity as an initial product-formation rate; matched mixtures, blanks and replication limit confounders.','Die lernende Person formuliert Hypothese, Variablen, Durchführung, Kontrollen, Wiederholungen, Messintervall und Auswertung selbstständig.','The learner independently specifies hypothesis, variables, protocol, controls, replication, measurement interval and analysis.'),
('Temperatur und pH beeinflussen Aktivität auf unterschiedliche Weise; reversible langsamere Reaktion ist von anhaltendem Aktivitätsverlust zu unterscheiden.','Temperature and pH influence activity in different ways; reversible slowing differs from persistent activity loss.','Die lernende Person wertet synthetische Anfangsraten aus und plant einen Rückführungsversuch statt jeden niedrigen Wert als Denaturierung zu bezeichnen.','The learner analyses synthetic initial rates and designs a return-to-baseline test rather than labelling every low value denaturation.'),
('Ein Messsignal ist ein begrenzter Indikator; Gasleckage, Substratverbrauch oder ein ungeprüfter Farbindikator können Schlussfolgerungen verändern.','A measurement signal is a limited indicator; gas leakage, substrate depletion or an unvalidated colour indicator can affect inference.','Die lernende Person verbessert den Plan bei einer neuen Störung und begründet, was die Daten über das getestete Enzym erlauben.','The learner improves the design for a fresh disturbance and explains what the data establish for the tested enzyme.')],
[('Temperaturvergleich versus gepufferter pH-Vergleich','Temperature comparison versus buffered pH comparison'),('Anfangsrate und Rückführung versus ungeeigneter Endpunkt','Initial rate and recovery test versus unsuitable endpoint')],[
C('enzyme-plan-c1',('Temperaturhypothese mit Katalase prüfen','Test a temperature hypothesis with catalase'),
('Schulgeeignete Materialien unter Lehrkraftaufsicht: identischer standardisierter Katalaseextrakt aus Kartoffel, verdünnte H₂O₂-Lösung höchstens 1 %, Wasserbäder 10/30/60 °C, Thermometer, pH-7-Puffer, Pipetten, Schutzbrillen und freigängig bewegliche Gasspritze mit Schlauch; kein starr verschlossener Gasraum. Reaktion: Katalase zerlegt H₂O₂, dabei entsteht O₂. Planungsauftrag ohne vorgegebenes Protokoll. Danach synthetische Pilotdaten für 1 ml Extrakt + 5 ml Substrat, drei unabhängige Ansätze je Temperatur: O₂ nach 0/20/40 s; 10 °C: 0/1,0/2,0; 0/1,1/2,2; 0/0,9/1,8 ml. 30 °C: 0/3,0/6,0; 0/3,2/6,4; 0/2,8/5,6 ml. 60 °C: 0/0,2/0,4; 0/0,3/0,6; 0/0,1/0,2 ml. Leeransatz ohne Enzym bei allen Temperaturen höchstens 0,1 ml in 40 s.','School-appropriate materials under teacher supervision: the same standardised potato catalase extract, dilute H₂O₂ at no more than 1%, 10/30/60 °C water baths, thermometer, pH-7 buffer, pipettes, goggles and a freely moving gas syringe with tubing; no rigid sealed gas space. Catalase breaks down H₂O₂ and releases O₂. Design task without a prescribed protocol. Subsequent synthetic pilot data for 1 ml extract plus 5 ml substrate, three independent mixtures per temperature: O₂ at 0/20/40 s; 10 °C: 0/1.0/2.0; 0/1.1/2.2; 0/0.9/1.8 ml. 30 °C: 0/3.0/6.0; 0/3.2/6.4; 0/2.8/5.6 ml. 60 °C: 0/0.2/0.4; 0/0.3/0.6; 0/0.1/0.2 ml. Enzyme-free blanks at all temperatures are at most 0.1 ml in 40 s.'),
('Plane vor der Datenauswertung selbstständig einen Versuch zur Hypothese: Innerhalb der getesteten Temperaturen ist die Anfangsrate bei 30 °C höher als bei 10 und 60 °C. Lege unabhängige/abhängige Variablen, gleiche Bedingungen, Kontrollen, drei unabhängige Ansätze, Start und Zeitmessung, sichere Gasführung und ein Auswertungskriterium fest. Berechne anschließend mittlere Anfangsraten aus den Pilotdaten und entwirf einen Zusatztest zum Unterschied zwischen Kälteverlangsamung und anhaltendem Hitzeverlust.','Before analysing the data, independently design a test of the hypothesis that the initial rate at 30 °C exceeds rates at 10 and 60 °C within these tested temperatures. Specify independent/dependent variables, matched conditions, controls, three independent mixtures, start/timing, safe gas collection and an analysis criterion. Then calculate mean initial rates from the pilot data and design a follow-up distinguishing cold slowing from persistent heat damage.'),
('Ein tragfähiger Plan variiert nur Temperatur, hält pH, Extrakt-/Substratmenge, Konzentrationen und Messapparatur gleich, temperiert getrennte Komponenten gleich lang und startet durch definierte Zugabe. Frische unabhängige Ansätze je Wiederholung, Reihenfolge rotieren, Gasdichtigkeit ohne Druckstau prüfen; Leeransatz ohne Enzym und hitzeinaktivierter Extrakt kontrollieren Hintergrund. Volumen alle 20 s in einem im Pilotversuch annähernd linearen Anfangsintervall erfassen. Mittlere Raten: 2,0/40 = 0,050; 6,0/40 = 0,150; 0,4/40 = 0,010 ml O₂/s, je Streubereich 0,045–0,055; 0,140–0,160; 0,005–0,015. Hypothese für diese Bedingungen gestützt, kein universelles Optimum bewiesen. Extrakt bei 10 bzw. 60 °C vorbehandeln und danach beide mit frischem Substrat bei 30 °C messen; Erholung versus bleibender Verlust unterscheiden.','A suitable plan varies only temperature, keeps pH, extract/substrate quantities, concentrations and apparatus equal, equilibrates separate components for equal times and starts with a defined addition. Use fresh independent mixtures for repeats, rotate order and check gas tightness without pressure buildup; enzyme-free and heat-inactivated-extract controls assess background. Measure every 20 s during a pilot-validated approximately linear initial interval. Mean rates: 2.0/40 = 0.050; 6.0/40 = 0.150; 0.4/40 = 0.010 ml O₂/s, with ranges 0.045–0.055, 0.140–0.160 and 0.005–0.015. The hypothesis is supported for these conditions; a universal optimum is not established. Pretreat extract at 10 or 60 °C, then assay both with fresh substrate at 30 °C to distinguish recovery from persistent loss.'),
('Ein neuer Datensatz zeigt bei 30 °C 0/3/5/5 ml nach 0/20/40/60 s. Eine Gruppe vergleicht ausschließlich das 60-s-Endvolumen verschiedener Temperaturen. Verbessere die Messentscheidung und nenne zwei mögliche Ursachen des Plateaus.','New data at 30 °C show 0/3/5/5 ml at 0/20/40/60 s. A group compares only 60-second endpoints across temperatures. Improve the measurement choice and name two possible plateau causes.'),
('Das Plateau macht den späten Endpunkt ungeeignet als alleinige Aktivitätsrate. Kürzere Anfangsintervalle mit ausreichend Substrat verwenden und Linearität prüfen; 0–20 s hier 0,15 ml/s. Substratverbrauch, Gasleckage oder Messbegrenzung sind mögliche Ursachen; aus dem Plateau allein folgt keine Enzymdenaturierung.','The plateau makes a late endpoint unsuitable as the sole activity-rate measure. Use shorter initial intervals with sufficient substrate and check linearity; here 0–20 s gives 0.15 ml/s. Substrate depletion, leakage or instrument limits are possible causes; the plateau alone does not prove enzyme denaturation.'),
('Synthetische Messwerte; kein tatsächlicher Laborlauf oder Lernendennachweis. Augen schützen, H₂O₂-Kontakt vermeiden, Hitzebäder nur unter Aufsicht, keine verschlossenen Druckgefäße. Die O₂-Volumenrate ist ein vergleichender Indikator unter gleicher Apparatur, keine universelle enzymatische Einheit.','Synthetic measurements; no actual laboratory run or learner evidence. Protect eyes, avoid H₂O₂ contact, supervise hot baths and avoid sealed pressure vessels. O₂ volume rate is a comparative indicator with matched apparatus, not a universal enzyme activity unit.'),
[('Eigenen vollständigen kontrollierten Plan mit Hypothese, Variablen, Kontrollen, Wiederholungen, sicheren Messschritten und Auswertung liefern.','Provide a complete independent controlled plan with hypothesis, variables, controls, replication, safe measurement and analysis.'),('0,050/0,150/0,010 ml/s auswerten; Rückführung und Grenzen der Denaturierungsdeutung erklären.','Analyse 0.050/0.150/0.010 ml/s; explain recovery testing and limits of denaturation inference.'),('Neues Plateau mit Anfangsintervall und prüfbaren Störhypothesen bearbeiten.','Address the fresh plateau using an initial interval and testable confounder hypotheses.')]),
C('enzyme-plan-c2',('pH-Einfluss ohne Farbindikatorfehler','Test pH effects without colour-indicator artefacts'),
('Schulmaterial: dasselbe Katalase-/H₂O₂-System, Puffer pH 5/7/9 mit gleicher Gesamtkonzentration, Wasserbad 25 °C, Gasspritze und Thermometer. Hypothesenthema ist pH, das Protokoll ist selbst zu entwerfen. Synthetische unabhängige Dreifachmessungen der O₂-Zunahme im geprüften linearen 30-s-Intervall bei gleichen Volumina: pH 5: 1,2/1,5/1,2 ml; pH 7: 3,0/3,3/3,0 ml; pH 9: 1,8/2,1/1,8 ml. Leerwerte je 0,0 ml. Ein alternativer Farbstoff wechselt bereits ohne Enzym bei pH 9 seine Farbe und ist deshalb als alleiniger Produktnachweis ungeeignet.','School materials: the same catalase/H₂O₂ system, equal-total-concentration buffers at pH 5/7/9, a 25 °C water bath, gas syringe and thermometer. The hypothesis concerns pH; the protocol is to be designed independently. Synthetic independent triplicates of O₂ increase during a validated linear 30-second interval with equal volumes: pH 5: 1.2/1.5/1.2 ml; pH 7: 3.0/3.3/3.0 ml; pH 9: 1.8/2.1/1.8 ml. Blanks are 0.0 ml. An alternative dye changes colour at pH 9 even without enzyme and is therefore unsuitable as the sole product indicator.'),
('Formuliere eine prüfbare pH-Hypothese und einen eigenen kontrollierten Plan mit operationalisierter Aktivitätsmessung. Begründe Pufferung, gleiche Temperatur und Blindansätze. Werte mittlere Raten aus und beurteile den Farbstoff. Plane einen Rückführungstest, bevor du Aktivitätsminderung als irreversible Strukturänderung deutest.','Formulate a testable pH hypothesis and your own controlled design with an operational activity measure. Explain buffering, constant temperature and blanks. Calculate mean rates and evaluate the dye. Design a return-to-baseline test before interpreting reduced activity as irreversible structural change.'),
('Beispielhypothese: Bei 25 °C zeigt das getestete Präparat bei pH 7 eine höhere Anfangsrate als bei pH 5/9. Nur pH ändern; gleiche Extraktcharge, Enzym-/Substratkonzentration, Volumen, Pufferkonzentration, Zeit, Temperatur und Apparatur; tatsächlichen pH nach Mischen prüfen. Drei frische Ansätze je pH, rotierende Startreihenfolge, definierter Start, gasdichte freigängige Spritze, Leeransätze ohne Enzym und positive pH-7-Referenz. Mittelvolumina 1,3/3,1/1,9 ml; Raten 0,0433/0,1033/0,0633 ml/s. Befund stützt die Beispielhypothese in den geprüften Stufen. Die Farbänderung im Leeransatz zeigt pH-Abhängigkeit des Indikators statt spezifischer Produktbildung. Nach Vorbehandlung bei pH 5 oder 9 auf pH 7 zurückführen und mit gleichen Verdünnungs-/Pufferkontrollen frisch testen; Erholung kann reversible Aktivitätsänderung stützen.','Example hypothesis: at 25 °C the tested preparation has a higher initial rate at pH 7 than at pH 5/9. Vary only pH; match extract batch, enzyme/substrate concentration, volume, buffer concentration, time, temperature and apparatus; check actual pH after mixing. Use three fresh mixtures per pH, rotated start order, defined start, gas-tight freely moving syringe, enzyme-free blanks and a positive pH-7 reference. Mean volumes are 1.3/3.1/1.9 ml; rates are 0.0433/0.1033/0.0633 ml/s. The finding supports the example hypothesis for the tested levels. Blank colour change reveals pH dependence of the indicator rather than specific product formation. After pH-5/9 pretreatment return to pH 7 and test fresh, with matched dilution/buffer controls; recovery can support a reversible activity change.'),
('Neue Bedingung: Gruppe A verdünnt beim Einstellen auf pH 5 den Extrakt doppelt so stark wie bei pH 7. Ihr pH-5-Wert ist halb so groß. Welche Planänderung ist notwendig und welcher Schluss ist bislang nicht erlaubt?','Fresh condition: group A dilutes extract twice as much when setting pH 5 as at pH 7. Its pH-5 reading is half as large. What design change is needed, and what conclusion is currently unsupported?'),
('Gleiche Enzymkonzentration und gleiche Gesamtvolumina herstellen bzw. Verdünnung als eigenen Faktor getrennt untersuchen. Der beobachtete Unterschied ist durch pH und Enzymmenge vermischt; ein reiner pH-Effekt ist bislang nicht identifiziert.','Match enzyme concentration and total volumes, or investigate dilution as a separate factor. The observed difference mixes pH with enzyme quantity; a pH-only effect has not yet been identified.'),
('Vorgegebene synthetische Daten belegen keine echte Durchführung. Puffer können zusätzliche Ionenwirkungen haben; die Aussage gilt für dieses Präparat und diese Bedingungen, nicht alle Enzyme. Schulische Chemikalien-/H₂O₂-Regeln wie im ersten Fall einhalten.','Supplied synthetic data do not establish actual performance. Buffers may have additional ionic effects; conclusions concern this preparation and these conditions rather than all enzymes. Follow school chemical/H₂O₂ rules as in the first case.'),
[('pH-Hypothese und eigener Plan kontrollieren Temperatur, Mengen, Puffer, Messstart, Wiederholungen und Kontrollen.','The pH hypothesis and independent design control temperature, quantities, buffer, start, repeats and controls.'),('Mittelraten korrekt berechnen und reversible Rückführung von irreversiblem Verlust trennen.','Calculate mean rates correctly and distinguish reversible recovery from persistent loss.'),('Farbleerwert und neuen Verdünnungsstörfaktor begründet auswerten.','Explain the dye blank and fresh dilution confounder.')])])

R(3,'modeling',[
('Enzymaktivität beeinflusst den Stofffluss; Rückkopplung durch ein Endprodukt kann einen frühen Reaktionsschritt bei hoher Produktverfügbarkeit bremsen.','Enzyme activity affects metabolic flux; end-product feedback can slow an early step when product availability is high.','Die lernende Person erklärt eine gegebene Rückkopplungskette mit Bindung, Aktivitätsänderung, Stofffluss und Versorgung.','The learner explains a supplied feedback pathway through binding, activity change, flux and supply.'),
('Reversible allosterische Regulation unterscheidet sich von Substratmangel, irreversibler Schädigung und langfristiger Veränderung der Enzymmenge.','Reversible allosteric regulation differs from substrate shortage, irreversible damage and longer-term changes in enzyme abundance.','Die lernende Person vergleicht Daten mit Kontrollbedingungen und unterscheidet die angegebenen Mechanismen.','The learner compares data with controls and distinguishes the specified mechanisms.'),
('Bedarfsgerechte Regulation beschreibt mechanistische Zustandsabhängigkeit und keine bewusste Absicht einer Zelle; ein neues gestörtes Glied verändert die Vorhersage.','Demand-responsive regulation describes state-dependent mechanisms rather than conscious cellular intention; a newly disrupted component changes predictions.','Die lernende Person sagt Folgen von Produktentzug oder Regulationsmutation im begrenzten Modell voraus.','The learner predicts product removal or regulatory-mutation effects within the bounded model.')],
[('Endproduktangebot und -entzug','End-product supply and removal'),('Aktivität pro Enzym versus Anzahl der Enzyme','Activity per enzyme versus enzyme abundance')],[
C('enzyme-regulation-c1',('Endprodukt bremst einen frühen Schritt','An end product slows an early step'),
('Didaktisches synthetisches Modell A —E1→ B —E2→ C. C bindet reversibel an eine regulatorische Stelle von E1, getrennt vom aktiven Zentrum. E1-Menge und A-Angebot sind konstant. Anfangsraten des ersten Schritts bei C = 0/2/5 mmol/l: 100/60/25 relative Einheiten. Nach Entfernung von C bei unveränderter E1-Menge: 98 Einheiten. Kontrolle mit regulatorischer Variante E1* ohne C-Bindestelle: 100/99/101 bei denselben C-Stufen. Keine Werte sind reale Patienten- oder Labordaten.','Synthetic teaching model A —E1→ B —E2→ C. C binds reversibly to a regulatory site of E1, separate from its active site. E1 abundance and A supply are constant. Initial rates of step one at C = 0/2/5 mmol/l: 100/60/25 relative units. After C removal with unchanged E1 abundance: 98 units. Regulatory variant E1* lacking the C-binding site: 100/99/101 at the same C levels. No values are real patient or laboratory data.'),
('Erkläre die Rückkopplung vom Endprodukt bis zum ersten Stofffluss und die Funktion für bedarfsgerechte Versorgung. Berechne die relative Abnahme bei 5 mmol/l. Begründe aus Entfernung und Variante, warum das Material reversible allosterische Hemmung und keine Zerstörung oder Vermehrung des Enzyms modelliert.','Explain feedback from end product to initial flux and its role in matching supply to demand. Calculate the relative decrease at 5 mmol/l. Use removal and the variant to explain why this material models reversible allosteric inhibition rather than enzyme destruction or multiplication.'),
('Steigt C, besetzt es die regulatorische Stelle; die funktionelle Enzymform/Aktivität verändert sich und weniger A wird pro Zeit umgesetzt. Bei hoher C-Verfügbarkeit entsteht weniger zusätzliches C; bei C-Verbrauch lässt die Hemmung nach. Abnahme (100−25)/100 = 75 %. Nach C-Entzug annähernd volle Aktivität und nahezu unveränderte E1*-Raten stützen den angegebenen reversiblen Bindungsmechanismus. Die Enzymmenge blieb konstant, deshalb wird keine Neusynthese erklärt. Das aktive Zentrum ist nicht der hier angegebene C-Bindeort. Zellen planen dies nicht bewusst.','As C rises it occupies the regulatory site; enzyme conformation/activity changes and less A is converted per time. High C availability reduces additional C formation; consuming C reduces inhibition. Decrease: (100−25)/100 = 75%. Near-full recovery after C removal and almost unchanged E1* rates support the supplied reversible binding mechanism. Enzyme abundance stayed constant, so no new synthesis is invoked. The active site is not the specified C-binding site. Cells do not consciously plan this.'),
('C wird plötzlich schneller verbraucht, A bleibt verfügbar. Sage den frühen Effekt bei E1 und E1* voraus und erkläre, warum daraus keine unbegrenzte Flusssteigerung folgt.','C is suddenly consumed faster while A remains available. Predict the early effect for E1 and E1* and explain why this does not imply unlimited flux increase.'),
('Bei E1 sinkt die regulatorische Belegung und die Rate kann innerhalb ihrer Kapazität steigen. E1* war schon nahezu ungebremst und zeigt keine entsprechende C-abhängige Enthemmung. Substratangebot, Enzymkapazität und weitere Schritte begrenzen den Fluss.','E1 regulatory occupancy falls and its rate can increase within its capacity. E1* was already nearly uninhibited and lacks the same C-dependent release. Substrate supply, enzyme capacity and downstream steps limit flux.'),
('Das Modell ist ausdrücklich allosterisch; nicht jede Endprodukthemmung nutzt identische Bindungsstellen oder Zahlen. Die Daten zeigen nur den modellierten ersten Schritt.','The model is explicitly allosteric; not every end-product inhibition uses identical sites or numbers. Data concern only the modelled first step.'),
[('C-Bindung → Aktivitätsabnahme → weniger Stofffluss als negative Rückkopplung erklären.','Explain C binding → lower activity → reduced flux as negative feedback.'),('75 %, reversible Erholung und konstante Enzymmenge materialgestützt unterscheiden.','Use the material to distinguish the 75% decrease, reversible recovery and constant enzyme abundance.'),('Neuen C-Verbrauch bei E1/E1* mit realen Kapazitätsgrenzen vorhersagen.','Predict fresh C consumption for E1/E1* with capacity limits.')]),
C('enzyme-regulation-c2',('Schnelle Aktivität und langsame Enzymmenge','Rapid activity and slower abundance changes'),
('Zwei synthetische Mechanismuskarten. System X: Ein kleines Regulationsmolekül bindet reversibel, innerhalb 30 s sinkt die Rate je Enzym von 8 auf 2 Einheiten, Enzymmenge 10 bleibt konstant; Entfernen stellt 8 wieder her. System Y: Ein Signal verändert die Enzymneubildung; nach 2 h sinkt die Anzahl von 10 auf 4, Rate je Enzym bleibt 8. Zusätzlich Z: Substrat ist fast aufgebraucht, Enzymmenge bleibt 10; neue Substratzugabe stellt den Fluss wieder her. Gesamtrate wird im vereinfachten Modell als Anzahl × Rate je Enzym berechnet.','Two synthetic mechanism cards. System X: a small regulatory molecule binds reversibly; within 30 seconds the rate per enzyme falls from 8 to 2 units while enzyme abundance stays 10; removal restores 8. System Y: a signal changes enzyme production; after two hours abundance falls from 10 to 4 while rate per enzyme remains 8. Additional Z: substrate is almost depleted while abundance stays 10; fresh substrate restores flux. Total rate in this simplified model equals abundance × rate per enzyme.'),
('Berechne Anfangs- und Endraten von X/Y. Erkläre, wie beide Systeme den Stoffwechsel regulieren, und unterscheide Z von direkter Enzymregulation. Plane zu einer unbekannten niedrigen Rate zwei gezielte Prüfungen, die Substratmangel und reversible Regulation auseinanderhalten.','Calculate initial/final total rates for X/Y. Explain how both regulate metabolism and distinguish Z from direct enzyme regulation. For an unknown low rate, design two targeted tests distinguishing substrate shortage from reversible regulation.'),
('Anfang jeweils 10×8 = 80. X: 10×2 = 20, schnelle Aktivitätsänderung vorhandener Enzyme; nach Molekülentzug 80. Y: 4×8 = 32, langsamere Mengenänderung; einzelne Enzyme arbeiten gleich. Z verringert den Fluss durch fehlendes Substrat, ohne den angegebenen Regulierungsmechanismus. Prüfungen an frischen gleichen Aliquots: konstante regulatorische Bedingungen plus Substratzugabe versus gleiche Substratsättigung plus Entfernung des Regulationsmoleküls; Kontrollen für Verdünnung, Zeit und Enzymmenge. Erholung nur mit Substrat stützt Mangel, nur nach Molekülentzug stützt reversible Regulation; Mischursachen bleiben möglich.','Initial totals are 10×8 = 80. X: 10×2 = 20, a rapid activity change in existing enzymes; regulator removal restores 80. Y: 4×8 = 32, a slower abundance change with unchanged individual-enzyme rate. Z lowers flux by substrate limitation without the specified regulatory mechanism. Use fresh matched aliquots: substrate addition at constant regulatory conditions versus regulator removal at matched substrate saturation; control dilution, time and enzyme amount. Recovery only with substrate supports shortage, only after regulator removal supports reversible regulation; combined causes remain possible.'),
('Eine neue Variante hat nach Signal weder weniger Enzyme noch veränderte Einzelrate, aber der nächste Wegschritt ist blockiert. Darf man aus normaler E1-Rate normalen Endproduktnachschub ableiten?','A new variant has neither lower abundance nor altered individual rate after the signal, but its next pathway step is blocked. Can a normal E1 rate establish normal end-product supply?'),
('Nein: Der Gesamtweg benötigt alle erforderlichen Schritte. Normaler erster Umsatz kann Zwischenprodukt ansammeln, während das Endprodukt fehlt. Die neue Blockade muss im Kettenmodell berücksichtigt werden; ein Einzelratenwert beschreibt nicht den ganzen Stoffwechsel.','No: the pathway requires all essential steps. A normal initial conversion can accumulate an intermediate while end product is missing. The fresh block must enter the pathway model; one step rate does not describe all metabolism.'),
('Das Produktmodell Anzahl×Rate gilt nur bei den angegebenen gleichen Bedingungen; echte Stoffwechselnetzwerke besitzen weitere Begrenzungen. Diese Aufgabe begründet keine molekulare Diagnose oder gesamte Genregulation.','The abundance×rate model holds only under the supplied matched conditions; real metabolic networks have further constraints. This task supports no molecular diagnosis or whole-gene-regulation approval.'),
[('Aktivitäts- und Mengenregulation als zwei Mechanismen bedarfsgerechten Stoffflusses erklären.','Explain activity and abundance regulation as two mechanisms of demand-responsive flux.'),('80→20 bzw. 80→32 berechnen und kontrollierte Unterscheidungsprüfungen planen.','Calculate 80→20 and 80→32 and design controlled discrimination tests.'),('Frische Wegblockade vom Einzelratenbefund trennen.','Distinguish a fresh pathway block from a single-step rate finding.')])])

R(4,'experiment',[
('Alkoholische Gärung führt von Pyruvat über CO₂-Abspaltung zu Ethanol; homolaktische Gärung führt zu Lactat ohne CO₂-Abspaltung. Beide regenerieren NAD⁺ für weitere Glykolyse.','Alcoholic fermentation converts pyruvate to ethanol with CO₂ release; homolactic fermentation converts it to lactate without CO₂ release. Both regenerate NAD⁺ for continued glycolysis.','Die lernende Person erklärt beide Wege einschließlich NADH/NAD⁺ und ordnet Gas-/Produktdaten korrekt zu.','The learner explains both pathways including NADH/NAD⁺ and correctly assigns gas/product data.'),
('Die Nettobilanz beträgt im Modell 2 ATP je Glucose aus der Glykolyse; die anschließende NAD⁺-Regeneration erzeugt kein zusätzliches ATP.','The model yields net 2 ATP per glucose from glycolysis; subsequent NAD⁺ regeneration produces no additional ATP.','Die lernende Person bilanziert ATP und plant kontrollierte Versuche mit geeignetem Produktnachweis, Referenz, Wiederholungen und sicheren definierten Kulturen.','The learner balances ATP and designs controlled experiments with suitable product detection, reference, replication and safe defined cultures.'),
('CO₂ und pH sind begrenzte Indikatoren: CO₂ allein unterscheidet nicht Atmung und Gärung; pH allein beweist kein Lactat.','CO₂ and pH are limited indicators: CO₂ alone does not distinguish respiration from fermentation; pH alone does not establish lactate.','Die lernende Person prüft eine neue widersprüchliche Beobachtung und fordert spezifischere Nachweise statt Schlussfolgerungen aus einem einzelnen Signal.','The learner evaluates a fresh conflicting observation and asks for more specific evidence instead of inferring from one signal.')],
[('Hefe und Ethanol/CO₂ versus definierter homolaktischer Starter und Lactat','Yeast with ethanol/CO₂ versus a defined homolactic starter with lactate'),('O₂-arme Bedingungen versus belüftete oder unspezifische Signale','Oxygen-poor conditions versus aerated or nonspecific signals')],[
C('fermentation-c1',('Alkoholische Gärung kontrolliert untersuchen','Investigate alcoholic fermentation with controls'),
('Material: definierte Backhefe, 2-%-Glucoselösung, 30-°C-Wasserbad, gleiche kleine Flaschen, weicher Ballon oder frei bewegliche Gasspritze, Stoppuhr; spezifischer schulgeeigneter Ethanoltest nach Hersteller-/Schulvorgabe durch die Lehrkraft. Ansätze nicht probieren und nicht starr gasdicht verschließen. Vorgabe: gleiche Hefecharge, O₂-arme Bedingungen mit wenig Lufteintrag; eine anfangs luftgefüllte Flasche ist nicht als exakt O₂-frei zu bezeichnen. Synthetische Pilotdaten mit drei unabhängigen Ansätzen je Gruppe nach 30 min: Hefe+Glucose, CO₂ 36/38/40 ml und Ethanol 7,6/8,0/8,4 mmol/l; Hefe ohne zugesetzte Glucose 2/3/2 ml und 0,3/0,4/0,3 mmol/l; hitzeinaktivierte Hefe+Glucose 0/1/0 ml und Ethanol unter Nachweisgrenze. Gemittelter Verlauf der aktiven Glucosegruppe bei 0/10/20/30 min: CO₂ 0/12/25/38 ml.','Materials: defined baker’s yeast, 2% glucose solution, 30 °C water bath, matched small bottles, a soft balloon or freely moving gas syringe and stopwatch; a specific school-appropriate ethanol test used by the teacher under product/school instructions. Do not taste mixtures or use rigid sealed vessels. Conditions: same yeast batch, oxygen-poor setup with little air entry; an initially air-filled bottle must not be called exactly oxygen-free. Synthetic pilot triplicates per group after 30 minutes: yeast+glucose, CO₂ 36/38/40 ml and ethanol 7.6/8.0/8.4 mmol/l; yeast without added glucose, 2/3/2 ml and 0.3/0.4/0.3 mmol/l; heat-inactivated yeast+glucose, 0/1/0 ml and ethanol below detection. Mean active-glucose time course at 0/10/20/30 min: CO₂ 0/12/25/38 ml.'),
('Plane einen realistisch durchführbaren Vergleich zur Hypothese: Unter diesen O₂-armen Bedingungen steigert zugesetzte Glucose die alkoholische Gärung. Lege Mengen, Kontrollgruppen, gleiche Temperatur/Zeit, unabhängige Wiederholungen, Gas- und Ethanolnachweis sowie sichere Durchführung fest. Werte anschließend die Pilotdaten aus; erkläre den Weg, NAD⁺-Regeneration und die ATP-Bilanz und vergleiche mit homolaktischer Gärung.','Design a feasible comparison for the hypothesis that added glucose increases alcoholic fermentation under these oxygen-poor conditions. Specify quantities, controls, equal temperature/time, independent replication, gas and ethanol detection and safety. Then analyse the pilot data; explain the pathway, NAD⁺ regeneration and ATP balance and compare it with homolactic fermentation.'),
('Geeigneter eigener Plan: z. B. 20 ml Lösung und gleiche Hefemasse je Flasche, gleiche O₂-arme Vorbereitung, 30 °C und 30 min; aktive Hefe+Glucose, aktive Hefe ohne Glucose und inaktivierte Hefe+Glucose, je drei frische Ansätze, rotierende Startreihenfolge. Gas in freigängiger Apparatur ohne Druckstau sammeln, Blind-/Positivkontrolle des Ethanoltests nutzen. Aktiv+Glucose liefert im Mittel 38 ml CO₂ und 8,0 mmol/l Ethanol, deutlich mehr als Kontrollen; Grundumsatz ohne Zusatz bleibt möglich. Glykolyse: Glucose → 2 Pyruvat, 4 ATP gebildet minus 2 eingesetzt = 2 netto, 2 NADH. Alkoholischer Anschluss setzt 2 CO₂ frei und reduziert Acetaldehyd zu 2 Ethanol; NADH wird dabei zu NAD⁺, ohne zusätzliches ATP. Homolaktischer Anschluss reduziert 2 Pyruvat zu 2 Lactat ohne CO₂ und regeneriert ebenfalls NAD⁺. Kombinierte Produktbefunde unter angegebenen Bedingungen stützen den Gärungsweg.','Suitable independent plan: for example, 20 ml solution and equal yeast mass per bottle, matched oxygen-poor preparation, 30 °C and 30 minutes; active yeast+glucose, active yeast without glucose and inactivated yeast+glucose, each with three fresh mixtures and rotated start order. Collect gas with free movement and no pressure buildup; use blank/positive controls for the ethanol assay. Active+glucose averages 38 ml CO₂ and 8.0 mmol/l ethanol, well above controls; basal activity without added sugar remains possible. Glycolysis: glucose → 2 pyruvate, 4 ATP made minus 2 invested = net 2, with 2 NADH. The alcoholic continuation releases 2 CO₂ and reduces acetaldehyde to 2 ethanol; NADH becomes NAD⁺ without additional ATP. Homolactic continuation reduces 2 pyruvate to 2 lactate without CO₂ and also regenerates NAD⁺. Combined product findings under the supplied conditions support the fermentation pathway.'),
('Ein neuer stark belüfteter Hefeansatz produziert CO₂, Ethanol bleibt unter Nachweisgrenze. Darf CO₂ allein als Beweis alkoholischer Gärung gelten? Welche Zusatzdaten würdest du verlangen?','A fresh strongly aerated yeast mixture produces CO₂ while ethanol remains below detection. Does CO₂ alone prove alcoholic fermentation? What additional data would you request?'),
('Nein: CO₂ kann auch bei aerober Atmung entstehen. O₂-Verbrauch und spezifischer Ethanolnachweis mit Kontrollen, Nachweisgrenze und passenden Vergleichsbedingungen helfen unterscheiden; Mischstoffwechsel bleibt möglich. Belüftung allein garantiert bei Hefe nicht unter allen Substratbedingungen ausschließlich Atmung.','No: aerobic respiration can also produce CO₂. Oxygen consumption and a specific ethanol assay with controls, detection limits and suitable comparison conditions help distinguish pathways; mixed metabolism remains possible. Aeration alone does not guarantee exclusively respiratory yeast metabolism under every substrate condition.'),
('Alle Daten synthetisch; keine reale Kultur oder Lernerprobung behauptet. Nur definierte schulgeeignete Hefe, Aufsicht und Herstellerregeln; kein Probieren, keine unbekannten Kulturen, keine Druckgefäße. Gasvolumen wird nicht ohne Temperatur-/Druck-/Löslichkeitskorrektur stöchiometrisch in Mol umgerechnet.','All data are synthetic; no actual culture or learner trial is claimed. Use only defined school-appropriate yeast, supervision and product rules; no tasting, unknown cultures or pressure vessels. Gas volume is not converted stoichiometrically into moles without temperature, pressure and solubility corrections.'),
[('Beide Gärungswege einschließlich CO₂-Unterschied und NAD⁺-Regeneration erklären.','Explain both fermentation pathways, the CO₂ difference and NAD⁺ regeneration.'),('Eigenen vollständigen Kontrollversuch und netto2ATP aus Glykolyse begründen; Mittelwerte auswerten.','Explain a complete independent controlled experiment and net2ATP from glycolysis; analyse means.'),('Frischen aerierten CO₂-Befund ohne Einzelsignal-Überdeutung bearbeiten.','Interpret the fresh aerated CO₂ finding without overclaiming from one signal.')]),
C('fermentation-c2',('Milchsäuregärung mit spezifischem Produktnachweis','Investigate lactic fermentation with specific product detection'),
('Material für eine schulisch freigegebene Untersuchung: definierter homofermentativer Lebensmittelstarter mit dokumentierter Glucosenutzung, steriles vorgegebenes Glucosemedium, pH-Meter mit Kalibrierlösungen und schulgeeigneter spezifischer Lactattest; Kulturansätze bleiben geschlossen für die Beobachtung, Gas darf über eine geeignete druckfreie Einrichtung entweichen, Probenahme nur nach Lehrkraftplan. Keine Lebensmittelproben unbekannter Keimzusammensetzung und kein Verzehr. Hypothese: aktiver Starter bildet aus Glucose Lactat, inaktivierter nicht. Synthetische Daten nach 4 h bei 30 °C, drei unabhängige Ansätze: aktiv – pH 4,4/4,5/4,4, Lactatzunahme 9,0/9,2/8,8 mmol/l und Glucoseabnahme 4,5/4,6/4,4 mmol/l; inaktiviert – pH 6,5/6,5/6,4, Lactatzunahme 0/0/0 und Glucoseabnahme 0/0/0. Ausgang pH 6,5; Lactat 0; Glucose 20 mmol/l. Kein CO₂ oberhalb der Nachweisgrenze im angegebenen homolaktischen Modell.','Materials for a school-authorised investigation: a defined homofermentative food starter with documented glucose use, supplied sterile glucose medium, calibrated pH meter and a school-appropriate specific lactate assay; mixtures remain closed for observation with a suitable pressure-free gas outlet, and sampling follows the teacher’s plan. No food samples of unknown microbial composition and no consumption. Hypothesis: active starter forms lactate from glucose whereas inactivated starter does not. Synthetic triplicate results after 4 h at 30 °C: active – pH 4.4/4.5/4.4, lactate increase 9.0/9.2/8.8 mmol/l and glucose decrease 4.5/4.6/4.4 mmol/l; inactivated – pH 6.5/6.5/6.4, lactate increase 0/0/0 and glucose decrease 0/0/0. Initially pH 6.5, lactate 0 and glucose 20 mmol/l. No CO₂ above detection in the supplied homolactic model.'),
('Entwirf selbstständig einen überprüfbaren Versuch mit gleichem Medium, Startermenge, Volumen, Temperatur, Zeit, Kontrollen und unabhängigen Wiederholungen. Lege pH- und Lactatmessung sowie Schulhygiene fest. Werte die mittleren Änderungen und das Verhältnis Lactat zu verbrauchter Glucose aus. Erkläre NAD⁺ und ATP, vergleiche mit alkoholischer Gärung und beurteile, was pH allein beweisen würde.','Independently design a test with matched medium, starter amount, volume, temperature, time, controls and independent replication. Specify pH/lactate measurement and school hygiene. Analyse mean changes and lactate per consumed glucose. Explain NAD⁺ and ATP, compare with alcoholic fermentation and evaluate what pH alone would establish.'),
('Plan: gleiches definiertes Medium, z. B. je 10 ml, gleiche aktive/inaktivierte Startermenge, je drei frische Ansätze und zusätzlich Medium ohne Starter; 30 °C/4 h, gleiche Probenzeiten, pH kalibrieren, Lactatassay mit Blind-/Standardkontrollen, dokumentierte Lehrkraftentnahme/Entsorgung. Aktiv: mittlere Lactatzunahme 9,0, Glucoseabnahme 4,5 mmol/l, Verhältnis 2:1; pH etwa4,4, Kontrollen nahezu unverändert. Im Modell passt Glucose → 2 Lactat. Glykolyse liefert netto2ATP und NADH; Lactatbildung oxidiert NADH zu NAD⁺ und erhält Glykolyse, ohne zusätzliches ATP. Alkoholische Gärung liefert Ethanol und CO₂ statt Lactat; homolaktische Gärung hier kein CO₂. pH-Abnahme zeigt Säurewirkung, aber erst spezifischer Lactatnachweis und passende Kontrollen stützen Lactatbildung.','Plan: the same defined medium, for example10 ml each, matched active/inactivated starter amounts, three fresh mixtures each plus starter-free medium; 30 °C/4 h with matched sampling times, calibrated pH, lactate assay with blank/standard controls, documented teacher sampling/disposal. Active means: lactate increases9.0 and glucose falls4.5 mmol/l, a2:1 ratio; pH is about4.4 while controls barely change. This fits the model glucose → 2 lactate. Glycolysis supplies net2ATP and NADH; lactate formation oxidises NADH to NAD⁺ and sustains glycolysis without additional ATP. Alcoholic fermentation forms ethanol and CO₂ instead of lactate; homolactic fermentation here forms no CO₂. Lower pH demonstrates an acid effect, but specific lactate detection and appropriate controls support lactate formation.'),
('Neues Medium ohne Starter wurde chemisch angesäuert: pH4,4, Lactat0. Ein anderer Starter bildet Lactat und Gas. Bewerte beide Befunde und die Aussage: Jede Milchsäuregärung bildet niemals Gas.','Fresh starter-free medium is chemically acidified: pH4.4, lactate0. Another starter forms lactate and gas. Evaluate both findings and the claim that every lactic fermentation never forms gas.'),
('Chemische Ansäuerung erklärt niedrigen pH ohne mikrobielle Lactatbildung. Beim anderen Starter muss der konkrete Weg geprüft werden; heterofermentative Wege können andere Produkte und CO₂ bilden. KeinGas gilt für das ausdrücklich vorgegebene homolaktische Modell, nicht pauschal für alle Milchsäuregärungen.','Chemical acidification explains low pH without microbial lactate formation. The other starter requires pathway identification; heterofermentative pathways can produce other products and CO₂. NoGas applies to the explicitly supplied homolactic model, not to every lactic fermentation.'),
('Synthetisches Versuchsmodell, kein bereits durchgeführter Kulturversuch. Nur institutionell erlaubte definierte Stämme und Lehrkraftprotokolle; pH logarithmisch, daher pH-Abnahme nicht linear als Lactatmenge interpretieren.','Synthetic experimental model, not a completed culture experiment. Use only institutionally permitted defined strains and teacher protocols; pH is logarithmic, so its decrease is not a linear lactate-quantity measure.'),
[('Lactatweg, alkoholischer Vergleich und NAD⁺-Regeneration korrekt erklären.','Correctly explain the lactate pathway, alcoholic comparison and NAD⁺ regeneration.'),('Vollständigen kontrollierten Plan, Verhältnis2:1 und netto2ATP aus Glykolyse liefern.','Provide a complete controlled plan, the2:1 ratio and net2ATP from glycolysis.'),('Chemische Ansäuerung und neuen gasbildenden Starter differenziert beurteilen.','Distinguish chemical acidification and the fresh gas-forming starter.')])])

R(5,'modeling',[
('Aerober vollständiger Glucoseabbau benötigt O₂ und ergibt CO₂/H₂O; Gärung lässt energiereiche organische Endprodukte zurück.','Complete aerobic glucose breakdown uses O₂ and yields CO₂/H₂O; fermentation leaves energy-rich organic end products.','Die lernende Person bilanziert die angegebenen Stoffwege und vergleicht Kohlenstoff- und Sauerstoffbilanzen.','The learner balances the supplied matter pathways and compares carbon and oxygen balances.'),
('Gärung liefert netto2ATP aus Glykolyse; ein angegebener aerober Modellwert ist größer, aber abhängig von Kopplung, Shuttles und Systemgrenzen.','Fermentation supplies net2ATP from glycolysis; a supplied aerobic model yield is larger but depends on coupling, shuttles and system boundaries.','Die lernende Person berechnet Nettobilanzen und relative Glucosebedarfe mit expliziten ATP-Modellannahmen.','The learner calculates net balances and relative glucose requirements using explicit ATP-model assumptions.'),
('O₂-Verfügbarkeit begünstigt aerobe Atmung nur bei geeigneter Zell-/Enzymausstattung; anaerobe Wege erhalten begrenzt ATP-Bildung und NAD⁺-Regeneration.','O₂ availability favours aerobic respiration only with suitable cellular/enzyme machinery; anaerobic pathways maintain limited ATP production and NAD⁺ regeneration.','Die lernende Person begründet Bedingungen und wertet einen neuen Versorgungs- oder Zellkontext ohne universelle Alles-oder-nichts-Regel aus.','The learner explains conditions and interprets a fresh supply or cell context without a universal all-or-none rule.')],
[('Aerobe Atmung versus alkoholische/homolaktische Gärung','Aerobic respiration versus alcoholic/homolactic fermentation'),('Modell30 versus Modell32ATP und neue Zellausstattung','Model30 versus model32ATP and new cellular machinery')],[
C('glucose-balance-c1',('Stoffgleichungen und ATP pro Glucose','Matter equations and ATP per glucose'),
('Gegebenes didaktisches Modell: Glucose C₆H₁₂O₆, aerobe Endprodukte CO₂/H₂O, alkoholische Endprodukte C₂H₆O/CO₂, homolaktische Endprodukte in der Summenform C₃H₆O₃ (Milchsäure; physiologisch überwiegend Lactat mit gesonderter Protonenbilanz). Glykolyse investiert2 und bildet4ATP. Für den vollständigen aeroben Weg gilt in diesem Aufgabenmodell netto30ATP je Glucose. Die Anschlussreaktionen der Gärung regenerieren NAD⁺ und liefern hier kein zusätzliches ATP. Modellbedarf einer Zelle:60ATP pro Zeiteinheit.','Supplied teaching model: glucose C₆H₁₂O₆; aerobic products CO₂/H₂O; alcoholic products C₂H₆O/CO₂; homolactic products written as C₃H₆O₃ (lactic acid; physiological lactate requires a separate proton balance). Glycolysis invests2 and produces4ATP. This problem assumes net30ATP per glucose for complete aerobic breakdown. Fermentation continuations regenerate NAD⁺ without additional ATP here. A model cell requires60ATP per time unit.'),
('Stelle die drei ausgeglichenen Stoffgleichungen auf und prüfe C/H/O. Vergleiche ATP-Nettogewinn sowie Glucosebedarf für60ATP. Erkläre mit organischen Endprodukten, warum geringe ATP-Ausbeute nicht bedeutet, dass Energie verschwindet; begründe die Bedingungen für die Wege.','Write the three balanced matter equations and check C/H/O. Compare netATP and glucose demand for60ATP. Use organic end products to explain why lowATP yield does not mean energy disappears; explain pathway conditions.'),
('Aerob: C₆H₁₂O₆+6O₂→6CO₂+6H₂O, beide Seiten C6/H12/O18. Alkoholisch: C₆H₁₂O₆→2C₂H₆O+2CO₂, C6/H12/O6. Homolaktische Summenform: C₆H₁₂O₆→2C₃H₆O₃, C6/H12/O6. Gärung netto4−2 =2ATP; aerob im gegebenen Modell30. Für60ATP:2 versus30Glucose, anaerober Bedarf15-mal höher im Modell. Ethanol/Lactat behalten chemische Energie; außerdem wird Energie als Wärme abgegeben. O₂ als terminaler Elektronenakzeptor ermöglicht geeigneten Zellen oxidative Phosphorylierung; O₂-Mangel begünstigt bei entsprechender Enzymausstattung Gärung zur NAD⁺-Regeneration. O₂ allein reicht ohne entsprechende Zellmaschinerie nicht.','Aerobic: C₆H₁₂O₆+6O₂→6CO₂+6H₂O, with C6/H12/O18 on both sides. Alcoholic: C₆H₁₂O₆→2C₂H₆O+2CO₂, C6/H12/O6. Homolactic summary: C₆H₁₂O₆→2C₃H₆O₃, C6/H12/O6. Fermentation nets4−2 =2ATP; aerobic yield is30 in this model. For60ATP:2 versus30glucose units, a15-fold anaerobic glucose requirement in the model. Ethanol/lactate retain chemical energy and some energy leaves as heat. O₂ as terminal electron acceptor enables oxidative phosphorylation in equipped cells; oxygen shortage favours fermentation for NAD⁺ regeneration when the necessary enzymes exist. O₂ alone is insufficient without cellular machinery.'),
('Neue Aufgabe verwendet netto32ATP für aeroben Abbau, sonst identische Bedingungen. Berechne den aeroben Bedarf für64ATP und den anaeroben Vergleich. Widerlegt32 den zuvor expliziten30er-Modellwert als universellen Fehler?','A fresh problem assumes net32ATP for aerobic breakdown with otherwise identical conditions. Calculate aerobic demand for64ATP and the anaerobic comparison. Does32 establish that the explicitly assumed30-model was universally wrong?'),
('64/32 =2Glucose aerob, 64/2 =32anaerob, Verhältnis16. Die Modellannahme ist geändert; ATP-Kopplung und Transport können Modellwerte beeinflussen. Weder30 noch32 wird als unveränderliche Ausbeute aller Zellen behauptet.','64/32 =2glucose aerobically,64/2 =32anaerobically, a16-fold ratio. The model assumption changed; coupling and transport can affect yields. Neither30 nor32 is asserted as the immutable yield of every cell.'),
('Stoffgleichungen sind Nettoübersichten ohne vollständige ATP/ADP/Phosphat-, Redox- und Protonenbuchführung. Kein Leistungs-, Ernährung- oder klinisches Modell.','Matter equations are net summaries without fullATP/ADP/phosphate, redox or proton bookkeeping. No performance, dietary or clinical model.'),
[('Drei C/H/O-ausgeglichene Stoffgleichungen und verbleibende organische Energie erklären.','Explain three C/H/O-balanced equations and remaining organic energy.'),('2/30ATP, Glucosebedarfe2/30 und neue2/32 korrekt unter Modellannahmen berechnen.','Calculate2/30ATP, glucose demands2/30 and the fresh2/32 under explicit model assumptions.'),('Bedingungen mit O₂ und geeigneter Zellausstattung begründen; Modellwechsel einordnen.','Explain oxygen plus suitable machinery requirements and interpret the changed model.')]),
C('glucose-balance-c2',('ATP-Versorgung bei O₂-Begrenzung','ATP supply under oxygen limitation'),
('Synthetische Zellmodelle mit geeigneten Gärungsenzymen: ModellA enthält funktionsfähige Mitochondrien, ModellB keine Mitochondrien. Vorgegebene Ausbeuten netto30ATP pro vollständig aerob abgebauter Glucose und netto2ATP pro vergorener Glucose. A setzt in einem Zeitfenster4Glucose aerob und6 homolaktisch um; B setzt10Glucose homolaktisch um, obwohl die Umgebung O₂ enthält. Keine Aussage über ein konkretes Organ oder eine Person. Für A sind die O₂-Mengen zum vollständigen Abbau von4Glucose verfügbar.','Synthetic cell models with suitable fermentation enzymes: modelA has functional mitochondria; modelB has no mitochondria. Supplied yields are net30ATP per completely aerobic glucose and net2ATP per fermented glucose. Within one interval, A processes4glucose aerobically and6 homolactically; B processes10glucose homolactically even though its surroundings contain O₂. No specific organ or person is modelled. A has enough oxygen for complete breakdown of4glucose.'),
('Bilanziere für A/B ATP, O₂-Verbrauch, CO₂- und Lactatbildung anhand der Nettoübersichten. Begründe die Unterschiede aus Bedingungen und Ausstattung. Erkläre, weshalb Gärung Glykolyse bei begrenzter oxidativer NADH-Nutzung ermöglicht und weshalb O₂-Anwesenheit kein universeller Umschalter ist.','BalanceATP, O₂ use and CO₂/lactate formation forA/B using the net summaries. Explain differences through conditions and machinery. Explain why fermentation permits glycolysis when oxidative NADH use is limited and why O₂ presence is not a universal switch.'),
('A:4×30+6×2 =132ATP;4×6 =24O₂ verbraucht,24CO₂ und12Lactat gebildet. B:10×2 =20ATP, keinO₂-Verbrauch/CO₂ in diesem homolaktischen Modell,20Lactat. A kann den aeroben Weg nutzen, aber das Zeitfenster bietet nur für den angegebenen Anteil genügendO₂; Gärung sichert NAD⁺ für weitere Glykolyse. B besitzt keine mitochondriale oxidative Maschinerie und kann sie durch O₂-Anwesenheit nicht ersetzen. In anderen Organismen oder Substratlagen können gleichzeitig verschiedene Wege auftreten; hier gelten die vorgegebenen Anteile.','A:4×30+6×2 =132ATP;4×6 =24O₂ consumed,24CO₂ and12lactate formed. B:10×2 =20ATP, noO₂ consumption/CO₂ in this homolactic model and20lactate. A can use respiration, but oxygen in this interval covers only the supplied portion; fermentation maintains NAD⁺ for continued glycolysis. B lacks mitochondrial oxidative machinery and oxygen presence cannot replace it. Other organisms or substrate conditions may use several pathways concurrently; here the supplied proportions apply.'),
('Neue Bedingung fürA: ausreichendO₂, aber die oxidative ATP-Kopplung ist stark eingeschränkt. Eine Gruppe verwendet weiterhin zwingend30ATP je Glucose. Welches Modell muss geprüft werden?','Fresh condition forA: oxygen is sufficient but oxidativeATP coupling is strongly impaired. A group still insists on30ATP per glucose. Which assumption needs checking?'),
('Der30er-Wert setzt die angegebene funktionsfähige Kopplung voraus. O₂-Verbrauch und CO₂-Bildung könnten bestehen, während weniger Energie inATP gebunden wird und mehr als Wärme abgeht. ATP-Ausbeute muss neu gemessen oder als neuer Modellwert gegeben werden; nicht automatisch auf30 oder auf reine Gärung setzen.','The30 yield assumes the supplied functional coupling. O₂ consumption and CO₂ production may continue while less energy is captured inATP and more leaves as heat. ATP yield needs new measurement or a new stipulated model value; do not automatically assign30 or exclusive fermentation.'),
('Synthetische Zellen und normierte Molekülmengen; keine reale Stoffwechselmessung. Homolaktische Protonen-/Wasserfeinbilanz sowie Nebenwege bleiben außerhalb der Aufgabe.','Synthetic cells and normalised molecule quantities; no real metabolic measurement. Detailed homolactic proton/water balance and side pathways are outside this task.'),
[('A/B-Stoffbilanzen24O₂/24CO₂/12Lactat versus20Lactat korrekt bilden.','Correctly balanceA/B:24O₂/24CO₂/12lactate versus20lactate.'),('132/20ATP mit ausdrücklich gegebenen Nettoausbeuten begründen.','Explain132/20ATP with the explicitly supplied net yields.'),('O₂-Ausstattung und frische Kopplungsstörung ohne pauschalen Umschalter erklären.','Explain oxygen, machinery and the fresh coupling impairment without a universal switch.')])])

R(6,'modeling',[
('Fette besitzen pro Gramm eine höhere nutzbare Nahrungsenergiedichte als Kohlenhydrate; der Vergleich benötigt dieselbe Bezugsgröße und ist nicht als bloßer Vergleich pro Mol zu begründen.','Fat has higher usable food-energy density per gram than carbohydrate; comparison requires the same reference quantity rather than simply comparing per mole.','Die lernende Person berechnet pro-Gramm-Werte, Stoffbilanzen und ausdrücklich modellierte ATP-Ausbeuten mit angegebenen Annahmen.','The learner calculates per-gram values, matter balances and explicitly modelled ATP yields using supplied assumptions.'),
('Reduzierte Kohlenstoffverbindungen und weitgehend wasserarme Speicherung tragen zur hohen Speicherenergiedichte von Fett bei; ATP-Zahl, Nahrungsenergie und gespeicherte Nassmasse sind verschiedene Größen.','Reduced carbon compounds and largely water-poor storage contribute to fat energy density; ATP count, food energy and stored wet mass are different quantities.','Die lernende Person erklärt den Speichervorteil aus Stoffstruktur und Hydratation und trennt die Berechnungsmodelle.','The learner explains the storage advantage through chemical reduction and hydration and keeps calculation models distinct.'),
('Palmitat ist ein begrenzter Modellvertreter, nicht die exakte Bilanz aller Fette; Aktivierung und Kopplungswerte verändern die ATP-Rechnung.','Palmitate is a bounded representative, not the exact balance of every fat; activation and coupling values affect ATP calculations.','Die lernende Person bearbeitet eine neue Modellannahme und begründet Grenzen und Bedingungen aerober Fettverwertung.','The learner handles a fresh model assumption and explains limits and conditions of aerobic fat use.')],
[('Gleiche Grammzahl versus verschiedene molare Massen','Equal grams versus different molar masses'),('Trockenstoff versus hydratisierter Speicher und geänderte ATP-Kopplung','Dry matter versus hydrated stores and altered ATP coupling')],[
C('fat-store-c1',('Gleiche Masse fair vergleichen','Compare equal masses fairly'),
('Didaktische Angaben: gerundete nutzbare Lebensmittelenergie Kohlenhydrate17kJ/g, Fett37kJ/g; im PNG werden genau1g gegenüber1g verglichen. Separates aerobes ATP-Modell: Glucose C₆H₁₂O₆,180g/mol, netto30molATP pro molGlucose; Palmitinsäure als Fettsäurevertreter C₁₆H₃₂O₂,256g/mol, netto106molATP pro mol nach Aktivierung. Beide werden vollständig zuCO₂/H₂O oxidiert. Die106 gelten für die im zweiten Fall erklärten Kopplungsannahmen; sie sind keine allgemeine feste ATP-Zahl aller Nahrungsfette.','Teaching values: rounded usable food energy is17kJ/g for carbohydrate and37kJ/g for fat; the PNG compares exactly1g with1g. Separate aerobicATP model: glucose C₆H₁₂O₆,180g/mol, net30molATP per molglucose; palmitic acid as a fatty-acid representative C₁₆H₃₂O₂,256g/mol, net106molATP per mol including activation cost. Both are completely oxidised toCO₂/H₂O. The106 yield assumes the coupling model explained in case2; it is not a fixedATP yield for every dietary fat.'),
('Vergleiche10g beider Nährstoffklassen energetisch. Bilanziere den vollständigen Stoffabbau von Glucose und Palmitinsäure. Berechne ATP pro Gramm nach dem separaten Modell und begründe, warum106 versus30 proMol allein kein fairer Massespeichervergleich ist. Erkläre die besondere Eignung von Fett als Speicher ohne Ernährungsempfehlung.','Compare food energy in10g of each nutrient class. Balance complete breakdown of glucose and palmitic acid. CalculateATP per gram in the separate model and explain why106 versus30 per mole alone is not a fair mass-storage comparison. Explain fat’s storage suitability without giving dietary advice.'),
('10g liefern modellhaft170 gegenüber370kJ, Verhältnis370/170≈2,18. Glucose: C₆H₁₂O₆+6O₂→6CO₂+6H₂O. Palmitinsäure: C₁₆H₃₂O₂+23O₂→16CO₂+16H₂O; C16/H32/O48 beidseits. ATP prog:30/180≈0,167molATP/g und106/256≈0,414molATP/g, Verhältnis≈2,48. ProMol enthalten die Stoffe unterschiedliche Masse und Kohlenstoffzahl; Normierung auf gleiche Gramm ist erforderlich. Stärker reduzierte Kohlenstoffverbindungen und weitgehend wasserarme Speicherung begünstigen Fettenergiedichte. Der2,18-Nahrungsenergiefaktor und2,48-ATP-Modellfaktor sind verschiedene Größen mit verschiedenen Stoff-/Kopplungsannahmen, kein Widerspruch.','10g supplies modelled170 versus370kJ, a370/170≈2.18 ratio. Glucose: C₆H₁₂O₆+6O₂→6CO₂+6H₂O. Palmitic acid: C₁₆H₃₂O₂+23O₂→16CO₂+16H₂O; both sides haveC16/H32/O48. ATP perg:30/180≈0.167molATP/g and106/256≈0.414molATP/g, ratio≈2.48. Per mole, masses and carbon counts differ; equal-gram normalisation is required. More reduced carbon compounds and largely water-poor storage favour fat energy density. The2.18 food-energy ratio and2.48ATP-model ratio are different quantities with different substrate/coupling assumptions, not a contradiction.'),
('Neue Rechnung gibt Palmitinsäureausbeute100ATP statt106, Glucose bleibt30. Berechne den pro-g-Vergleich neu und prüfe, ob die Aussage höhere Fettenergiedichte dadurch automatisch entfällt.','Fresh calculation uses100ATP per palmitic acid instead of106, with glucose still30. Recalculate the per-gram comparison and examine whether this automatically removes fat’s higher energy density.'),
('100/256≈0,391molATP/g gegenüber0,167, Verhältnis≈2,34. Im neuen Modell bleibt der ATP-pro-g-Wert höher. Der konkrete Modellfaktor ändert sich; die vorgegebenen gerundeten Lebensmittelenergieangaben werden durch eine andere ATP-Kopplungsannahme nicht automatisch ersetzt.','100/256≈0.391molATP/g versus0.167, ratio≈2.34. ATP perg remains higher in the fresh model. The numerical model factor changes; anotherATP-coupling assumption does not automatically replace the supplied rounded food-energy values.'),
('Nahrungsfette sind überwiegend Triacylglycerine; Palmitinsäure ist ein vereinfachter Fettsäurevertreter, keine Gesamtbilanz jedes Speichermoleküls. Netto-Stoffgleichungen lassen ATP/ADP, Cofaktoren und einzelne Reaktionsschritte aus. Keine klinische, Sport- oder Ernährungsberatung.','Dietary fats are mostly triacylglycerols; palmitic acid is a simplified fatty-acid representative, not the complete balance for every storage molecule. Net matter equations omitATP/ADP, cofactors and individual steps. No clinical, sports or dietary advice.'),
[('Stoffgleichungen und faire ATP-/Energie-Normierung pro Gramm korrekt darstellen.','Correctly represent matter equations and fairATP/energy normalisation per gram.'),('170/370kJ,0,167/0,414molATP/g und unterschiedliche Modellgrößen begründen.','Explain170/370kJ,0.167/0.414molATP/g and the distinct model quantities.'),('Frische100er-Annahme zu0,391 und Verhältnis2,34 korrekt bearbeiten.','Handle the fresh100 assumption correctly to obtain0.391 and ratio2.34.')]),
C('fat-store-c2',('Aktivierung, Hydratation und Speicherbilanz','Activation, hydration and storage balance'),
('Gegebenes Modell für Palmitat:7β-Oxidationszyklen ergeben7NADH,7FADH₂ und8Acetyl-CoA; proAcetyl-CoA im Citratzyklus10ATP-Äquivalente, proNADH2,5 und proFADH₂1,5; Fettsäureaktivierung kostet2ATP-Äquivalente. Zusatzmodell Speicher:100g trockenes Glykogen bindet hier300gWasser,100gFett wird vereinfachend ohne Zusatzwasser gespeichert. Energiewerte17kJ/g trockenes Kohlenhydrat und37kJ/gFett. Glucosevergleich:30ATP bei180g/mol; Palmitat256g/mol. Synthetische Modellangaben, keine Messung einer Person.','Supplied palmitate model:7β-oxidation cycles yield7NADH,7FADH₂ and8acetyl-CoA; each acetyl-CoA yields10ATP equivalents in the citric-acid cycle, eachNADH2.5 and eachFADH₂1.5; fatty-acid activation costs2ATP equivalents. Additional storage model:100g dry glycogen binds300gwater here, whereas100gfat is stored without additional water in this simplification. Energy values are17kJ/g dry carbohydrate and37kJ/gfat. Glucose comparison:30ATP at180g/mol; palmitate256g/mol. These are synthetic model assumptions, not measurements of a person.'),
('Leite106ATP rechnerisch her und vermeide doppeltes Abziehen der Aktivierung. Vergleiche Energie pro Gramm gesamter gespeicherter Masse für beide Speicher. Erkläre Stoff- und Speichervorteile sowie notwendige Bedingungen aerober Fettverwertung. Stelle klar, welche Angaben Stoffbilanz, ATP-Modell und Hydratation betreffen.','Derive106ATP and avoid subtracting activation twice. Compare energy per gram of total stored mass in the two reserves. Explain chemical/storage advantages and conditions for aerobic fat use. Distinguish matter balance,ATP model and hydration assumptions.'),
('ATP:7×2,5+7×1,5+8×10−2 =17,5+10,5+80−2 =106. Die106 sind bereits netto inklusive einmaliger Aktivierung.100gGlykogen enthalten1700kJ in400gNassspeicher, also4,25kJ/gGesamtmasse;100gFett enthalten3700kJ in100g, also37kJ/g, Faktor37/4,25≈8,71 im angegebenen Hydratationsmodell. ProTrockenmasse bleibt der gerundete Faktor37/17≈2,18; ATP perg folgt separat106/256 versus30/180. Wasserarme Speicherung und stärker reduzierte Kohlenstoffverbindungen erhöhen gespeicherte Energie je Masse. Vollständiger Fettabbau erfordert geeignete Enzyme und funktionsfähige oxidative Stoffwechselbedingungen/O₂; hohe Speicherenergiedichte bedeutet nicht universell schnellere Bereitstellung.','ATP:7×2.5+7×1.5+8×10−2 =17.5+10.5+80−2 =106. The106 yield already includes the activation cost once.100gglycogen contains1700kJ in400g of hydrated stores, giving4.25kJ/g total mass;100gfat contains3700kJ in100g, giving37kJ/g, a37/4.25≈8.71 ratio in this hydration model. The rounded dry-mass ratio remains37/17≈2.18; ATP perg separately follows106/256 versus30/180. Water-poor storage and more reduced carbon compounds increase stored energy per mass. Complete fat breakdown needs suitable enzymes and functional oxidative conditions/O₂; high storage energy density does not mean universally faster availability.'),
('Neue Annahme: proNADH2 und proFADH₂1ATP, proAcetyl-CoA entsprechend8ATP-Äquivalente; Aktivierung bleibt2. Berechne NettoATP und pro-g-Wert für Palmitat. Darfst du aus diesem Wechsel ein genaues ATP-Ergebnis für alle Triacylglycerine ableiten?','Fresh assumptions:2ATP perNADH and1 perFADH₂, correspondingly8ATP equivalents peracetyl-CoA; activation remains2. Calculate netATP and palmitateATP perg. Can this establish one exactATP yield for all triacylglycerols?'),
('7×2+7×1+8×8−2 =14+7+64−2 =83ATP;83/256≈0,324molATP/g. Nein: Zusammensetzung und Kettenlängen/Unsättigung sowie Glycerolanteil und Kopplung unterscheiden sich. Die Rechnung ist eine explizit veränderte Palmitat-Modellbilanz, keine pauschale Fettgleichung.','7×2+7×1+8×8−2 =14+7+64−2 =83ATP;83/256≈0.324molATP/g. No: composition, chain lengths/unsaturation, glycerol and coupling differ. This is an explicitly altered palmitate-model balance, not a universal fat equation.'),
('300gWasser pro100gGlykogen ist eine gesetzte didaktische Annahme; tatsächliche Hydratation variiert. Wasserarme Fettlager werden vereinfacht; Begleitgewebe ist nicht bilanziert. Keine individualisierte Gesundheits- oder Ernährungsfreigabe.','300gwater per100gglycogen is a stipulated teaching assumption; actual hydration varies. Water-poor fat storage is simplified and accompanying tissue is not included. No individual health or nutrition approval.'),
[('106ATP einmal netto und pro-g-Bezugsgröße korrekt berechnen.','Correctly calculate106ATP net once and use the per-gram reference.'),('4,25/37kJ pro Nassgramm mit Hydratationsannahme und Reduktionszustand erklären.','Explain4.25/37kJ per hydrated gram using hydration and chemical reduction.'),('Neue83ATP/0,324mol/g herleiten und Palmitat-/Gesamtfettgrenze benennen.','Derive the fresh83ATP/0.324mol/g and identify the palmitate/whole-fat boundary.')])])

R(7,'concept',[
('Mikroorganismen nutzen Lebensmittelbestandteile für Stoffwechsel und können sich unter geeigneten Bedingungen vermehren; ihre Produkte können Geruch, Säure, Gas und Strukturveränderung verursachen.','Microorganisms use food components metabolically and can multiply under suitable conditions; their products may cause odour, acid, gas and structural changes.','Die lernende Person verbindet gegebenen Stoffwechsel und Vermehrung mit begrenzten Verderbbeobachtungen.','The learner connects supplied metabolism and multiplication to bounded spoilage observations.'),
('Ausbreitung erfolgt unter anderem durch Hände, Geräte oder Sporen; Kühlen verlangsamt viele Prozesse, Trennen und Reinigen begrenzen Übertragung, ohne pauschale Sterilität zu garantieren.','Spread occurs through hands, utensils or spores; cooling slows many processes, while separation and cleaning limit transfer without guaranteeing sterility.','Die lernende Person leitet konkrete Hygienehandlungen aus einem beschriebenen Übertragungs- und Wachstumsweg ab.','The learner derives concrete hygiene actions from a described transfer and growth pathway.'),
('Verderb und Krankheitserreger sind nicht gleichzusetzen: gefährliche Belastung muss nicht sichtbar oder riechbar sein, sichtbarer Verderb beweist keinen bestimmten Erreger.','Spoilage and pathogens are not equivalent: harmful contamination need not be visible or smellable, and visible spoilage does not identify a particular pathogen.','Die lernende Person beurteilt einen neuen unauffälligen oder sichtbar veränderten Befund ohne Sicht-/Geruchssicherheitsfreigabe.','The learner evaluates a fresh normal-looking or visibly changed observation without granting safety from appearance or smell.')],
[('Temperaturabhängige Vermehrung versus Übertragung','Temperature-dependent multiplication versus transfer'),('Sichtbarer Verderb versus unauffälliger unbekannter Zustand','Visible spoilage versus an unremarkable unknown condition')],[
C('food-hygiene-c1',('Wachstum und Verderb unter Modellbedingungen','Growth and spoilage under model conditions'),
('Nur bereitgestellte synthetische Daten, kein Kultivieren oder Probieren verdorbener Lebensmittel. Definierter Modellorganismus in einem vorgegebenen nährstoffhaltigen Medium: Anfang jeweils100relative vermehrungsfähige Einheiten. Nach0/2/4h bei20°C:100/400/1600; bei4°C:100/110/120. Der Organismus erzeugt in diesem Modell organische Säuren und Geruchsstoffe; anfangs sind keine Veränderungen wahrnehmbar. Vergleichskarten: einige Bakterien vermehren sich durch Zweiteilung, viele Hefen durch Sprossung, Schimmelpilze wachsen als Hyphen und können über Sporen verbreitet werden. Die Zahlen gelten ausschließlich für diesen vorgegebenen Organismus/dieses Medium.','Provided synthetic data only; no culturing or tasting spoiled food. A defined model organism in supplied nutrient medium starts at100relative viable units in both groups. At0/2/4h at20°C:100/400/1600; at4°C:100/110/120. This model organism forms organic acids and odour compounds; no changes are initially perceptible. Comparison cards: some bacteria multiply by binary fission, many yeasts by budding, and moulds grow as hyphae and may spread through spores. Numbers apply only to this supplied organism/medium.'),
('Erkläre die Verknüpfung von Nährstoffnutzung, Vermehrung und Verderb. Vergleiche die Daten und leite die Bedeutung der Kühlung ab. Unterscheide die angegebenen Vermehrungsformen. Prüfe die Aussagen: Kühlen tötet alle Keime; ein normaler Geruch beweist sichere Lebensmittel; jeder Verderbkeim ist ein Krankheitserreger.','Explain the link between nutrient use, multiplication and spoilage. Compare the data and derive the role of cooling. Distinguish the supplied multiplication forms. Evaluate the claims that cooling kills all microbes, normal smell proves food safety and every spoilage microbe is a pathogen.'),
('Nährstoffe ermöglichen Stoffwechsel und unter geeigneten Bedingungen Vermehrung; angesammelte Stoffwechselprodukte können Säure/Geruch/Struktur verändern. Warm steigt der Modellwert16-fach, gekühlt1,2-fach, Kühlung verlangsamt hier, sterilisiert aber nicht. Zweiteilung teilt eine Bakterienzelle, Sprossung bildet eine Tochterknospe; Hyphenwachstum und Sporenübertragung sind andere Vorgänge. Alle drei Sicherheitsbehauptungen sind unbegründet: lebende Einheiten bleiben gekühlt, krankheitserregende Belastung kann ohne auffälligen Geruch bestehen, und Verderberreger/Krankheitserreger sind unterschiedliche Kategorien mit möglichen Überschneidungen. Keine Verkostung als Test.','Nutrients support metabolism and multiplication under suitable conditions; accumulated products may change acidity, odour or texture. The warm model value rises16-fold and the cooled value1.2-fold; cooling slows this model but does not sterilise it. Binary fission divides a bacterial cell, budding produces a daughter bud; hyphal growth and spore transfer are different processes. All three safety claims are unsupported: viable units remain when cooled, pathogens may be present without unusual smell, and spoilage organisms/pathogens are distinct categories that may overlap. Tasting is not a test.'),
('Neuer Organismus wächst unter denselben4°C-Bedingungen stärker als der Modellorganismus. Darf die ursprüngliche Tabelle eine allgemeine Haltbarkeitsdauer oder völlige Kühl-Sicherheit festlegen?','A fresh organism grows faster under the same4°C conditions than the model organism. Can the original table establish a general shelf-life or complete refrigerated safety?'),
('Nein: Temperaturreaktion ist organismen-/mediumabhängig; Ausgangsbelastung und Zeit spielen mit. Die Tabelle stützt nur den Vergleich im gegebenen Modell. Konkrete Lagerhinweise benötigen passende Produkt-/Schulvorgaben, nicht eine pauschale Frist aus diesen Übungszahlen.','No: temperature response depends on organism and medium, with initial contamination and time also relevant. The table supports only the supplied model comparison. Actual storage instructions require appropriate product/school rules rather than a universal deadline from practice numbers.'),
('Synthetische relative Einheiten sind keine reale Keimzahl und keine Sicherheitsgrenzwerte. Unbekannte Mikroorganismen werden nicht im Schulversuch kultiviert oder durch Geruch/Verzehr geprüft. Keine gesetzlichen/medizinischen Lagergrenzen werden freigegeben.','Synthetic relative units are not actual microbial counts or safety thresholds. Unknown organisms are not cultured in the school activity or tested by smell/tasting. No legal or medical storage thresholds are approved.'),
[('Stoffwechselprodukte, geeignete Bedingungen und verschiedene Vermehrungsformen erklären.','Explain metabolic products, suitable conditions and different multiplication forms.'),('16-/1,2-fachen Vergleich als Verlangsamung mit Grenzen der Kühlung begründen.','Explain the16-/1.2-fold comparison as slowing with limits of refrigeration.'),('Normaler Geruch und neue kältetolerante Variante ohne Sicherheitsschluss einordnen.','Interpret normal smell and the fresh cold-tolerant variant without a safety conclusion.')]),
C('food-hygiene-c2',('Übertragung sichtbar modellieren','Model transfer visibly'),
('Nichtbiologische Unterrichtssimulation: fluoreszierende Markierung auf einem Modell für rohes Lebensmittel. Eine ungewaschene Modellhand berührt das erste Brett, danach ein Modell für verzehrfertiges Lebensmittel auf demselben Brett. Synthetische Fluoreszenzwerte: Ausgangsmarkierung100relative Einheiten, Brett35, verzehrfertiges Modell12. Variante mit getrenntem sauberem Brett, gründlicher Hand-/Oberflächenreinigung nach vorgegebenem Schulablauf: Zielsignal1; Blindversuch ohne Markierung0. Fluoreszenz ist ein Übertragungsindikator, keine Keimzahl und kein Wirksamkeitstest gegen einen bestimmten Erreger. Zusatzkarten: Schimmelsporen können über Luft oder Oberflächen übertragen werden; sichtbare Pilzkolonie kann weiter reichende nicht sichtbare Hyphen besitzen; Krankheitserreger können ohne sichtbaren Verderb vorkommen.','Nonbiological classroom simulation: fluorescent marker on a raw-food model. An unwashed model hand touches the first board, then a ready-to-eat food model on the same board. Synthetic fluorescence: initial marker100relative units, board35, ready-to-eat model12. With a separate clean board and thorough hand/surface cleaning under a supplied school procedure, target signal is1; unmarked blank0. Fluorescence indicates transfer, not microbial numbers or effectiveness against a particular pathogen. Additional cards: mould spores can spread through air or surfaces; a visible mould colony may have more extensive invisible hyphae; pathogens may occur without visible spoilage.'),
('Beschreibe den Übertragungsweg und begründe Trennen, Reinigen und Kühlen aus jeweils unterschiedlichen Wirkungen. Werte die Simulation aus und benenne ihre Grenzen. Erkläre anhand der Karten, weshalb das Abwischen einer sichtbaren Stelle oder normales Aussehen keine allgemeine Sicherheitsprüfung ist.','Describe the transfer route and explain distinct reasons for separating, cleaning and cooling. Analyse the simulation and state its limits. Use the cards to explain why wiping a visible spot or normal appearance is not a general safety test.'),
('Markierung geht vom Modell über Hand/Brett zum verzehrfertigen Modell; getrennte saubere Arbeitswege und Reinigung verringern diesen Transport, hier Signal12→1. Kühlen greift vor allem bei Wachstum/Stoffwechsel während Lagerung an und verhindert nicht automatisch vorherige Übertragung. Der Restwert zeigt keine garantierte vollständige Entfernung; der Marker misst weder Vermehrung noch Abtötung von Keimen. Sporen können neu eingetragen werden; nicht sichtbare Hyphen bzw. unauffällige Krankheitserreger begrenzen Schlussfolgerungen aus sichtbaren Stellen. Konkrete Lebensmittelbeurteilung richtet sich nach geeigneten Vorgaben und keinem Unterrichts-Geruchs-/Probiertest.','Marker travels through hand/board to the ready-to-eat model; separate clean work paths and cleaning reduce transfer, here signal12→1. Cooling mainly affects growth/metabolism during storage and does not automatically prevent earlier transfer. The remaining signal does not guarantee complete removal; the marker measures neither microbial multiplication nor killing. Spores can arrive anew, and invisible hyphae or unremarkable pathogens limit conclusions from visible spots. Actual food evaluation follows suitable guidance rather than a classroom smell/taste test.'),
('Neue Simulation: Sauberes Brett, aber dieselbe markierte Hand berührt direkt das verzehrfertige Modell; Zielsignal9. Eine andere Gruppe sieht bei einem Lebensmittel keinen Schimmel. Welche getrennten Schlüsse und Handlungen sind begründet?','Fresh simulation: a clean board is used, but the same marked hand directly touches the ready-to-eat model; target signal9. Another group sees no mould on a food item. Which separate conclusions and actions are justified?'),
('Direkter Handkontakt umgeht die Bretttrennung; auch Hände/Arbeitsfolge müssen berücksichtigt und nach Vorgaben gereinigt werden. Keine sichtbare Schimmelkolonie bedeutet nur kein sichtbarer Schimmelbefund, nicht frei von Krankheitserregern oder sonst sicher. Der Übertragungsmarker darf nicht als reale infektiöse Dosis interpretiert werden.','Direct hand contact bypasses board separation; hands and work sequence also need attention and cleaning under the rules. No visible mould means only no visible mould finding, not pathogen-free or otherwise safe. Transfer marker is not an actual infectious dose.'),
('Nur nichtbiologische Simulation und synthetische Signalwerte; keine echte Lebensmittelmikrobiologie, Desinfektionswirksamkeit oder Lernendenerprobung. Kein Verzehr oder Kultivieren unbekannter Proben.','Only a nonbiological simulation with synthetic signals; no actual food microbiology, disinfection-efficacy study or learner trial. No consumption or culturing of unknown samples.'),
[('Übertragung und organismusspezifische Vermehrung als unterschiedliche Vorgänge erklären.','Explain transfer and organism-specific multiplication as different processes.'),('Trennen/Reinigen/Kühlen mit jeweils passender Ursache und Markergrenze begründen.','Explain separation/cleaning/cooling through appropriate mechanisms and marker limits.'),('Direkte neue Handübertragung und fehlenden sichtbaren Verderb ohne Freigabe beurteilen.','Evaluate fresh direct hand transfer and absent visible spoilage without approving safety.')])])

assert len(records)==8 and sum(len(x['cases']) for x in records)==16
out={'schemaVersion':1,'role':'Own original whole bilingual scientific AUTHOR candidates; independent reviews pending','license':'CC-BY-4.0','attribution':'SkillPilot','sourceWitnessesReusedWithoutNewSourceReview':50,'legacyPassageObjectsRetainedAsNull':25,'records':records,'humanApproval':False,'learnerWork':False,'evidenceLevel':'E1','maximumClaimScope':'G1','reviewAuthority':'ai_candidate','status':'needs_human_review'}
